/**
 * Converts violations to GitHub inline annotations (PRE-329).
 *
 * Uses @actions/core to emit annotations that appear on the PR diff.
 */

import * as core from '@actions/core';
import type { ActionResult } from './types.js';
import { annotationLevel } from './severity.js';

export function createAnnotations(result: ActionResult): void {
  for (const fv of result.fileViolations) {
    for (const v of fv.violations) {
      const properties: core.AnnotationProperties = {
        file: fv.path,
        startLine: v.line,
        title: `preset/${v.ruleId}`,
      };

      // PRE-2665: an advisory finding is a notice. core.warning() put a
      // yellow annotation on the diff for a rule that is deliberately not
      // enforced, which reads to a human as a problem.
      const level = annotationLevel(v.severity);
      if (level === 'error') core.error(v.fix, properties);
      else if (level === 'notice') core.notice(v.fix, properties);
      else core.warning(v.fix, properties);
    }
  }
}
