/**
 * Configuration parser for the Preset GitHub Action (PRE-329).
 *
 * Merges action inputs (from action.yml) with optional .presetrc file.
 */

import * as core from '@actions/core';
import * as fs from 'node:fs';
import * as path from 'node:path';
import type { ActionConfig } from './types.js';
import { resolveFailOnErrors, type ModeValue } from './fail-on-errors.js';

/**
 * `.presetrc` shape. Mirrors the 7-field PRESETRC_ALLOWLIST in the
 * mcp-gateway agent-events endpoint (PRE-943 T8 privacy boundary), plus
 * `mode` (PRE-3040/PRE-3041), which is read for live runtime precedence
 * only and is never reported through the callback's allowlist.
 */
export interface PresetRc {
  include?: string[];
  exclude?: string[];
  failOnErrors?: boolean;
  failOnWarnings?: boolean;
  compositionChecks?: boolean;
  scoreThreshold?: number;
  regressionThreshold?: number;
  failOnNewOnly?: boolean;
  /**
   * PRE-3040: the Action now reads this live, at runtime, on every run, not
   * only at `preset ci init` time. See `resolveFailOnErrors` (fail-on-errors.ts)
   * for the full precedence and the shadow-precedence warning.
   */
  mode?: ModeValue;
}

export function loadPresetRc(): PresetRc | null {
  const rcPath = path.resolve(process.cwd(), '.presetrc');
  if (!fs.existsSync(rcPath)) return null;

  try {
    const raw = fs.readFileSync(rcPath, 'utf-8');
    return JSON.parse(raw) as PresetRc;
  } catch (e) {
    core.warning(`.presetrc found but could not be parsed: ${e}`);
    return null;
  }
}

export function parseConfig(): ActionConfig {
  const rc = loadPresetRc();

  const includeInput = core.getInput('include');
  const excludeInput = core.getInput('exclude');

  const include = rc?.include
    ?? (includeInput ? includeInput.split(',').map(s => s.trim()) : ['**/*.tsx', '**/*.jsx', '**/*.ts', '**/*.vue', '**/*.svelte']);
  const exclude = rc?.exclude
    ?? (excludeInput ? excludeInput.split(',').map(s => s.trim()) : ['**/node_modules/**']);

  // PRE-3040/PRE-3041: explicit .presetrc.failOnErrors > explicit fail-on-errors
  // input > .presetrc.mode > hardcoded default. See fail-on-errors.ts for the
  // full precedence and the shadow-precedence warning this surfaces.
  const failOnErrorsResolution = resolveFailOnErrors(rc, core.getInput('fail-on-errors'));
  if (failOnErrorsResolution.warning) core.warning(failOnErrorsResolution.warning);

  return {
    githubToken: core.getInput('github-token') || process.env.GITHUB_TOKEN || '',
    supabaseUrl: core.getInput('supabase-url') || undefined,
    supabaseKey: core.getInput('supabase-key') || undefined,
    designSystemId: core.getInput('design-system-id') || undefined,
    layerId: core.getInput('layer-id') || undefined,
    include,
    exclude,
    failOnErrors: failOnErrorsResolution.value,
    failOnWarnings: rc?.failOnWarnings ?? core.getInput('fail-on-warnings') === 'true',
    compositionChecks: rc?.compositionChecks ?? core.getInput('composition-checks') === 'true',
    // PRE-1933: opt-in autofix. Action input only (not a .presetrc field) — it's
    // a CI behavior toggle that mutates the PR branch, kept explicit per-workflow.
    applyFixes: core.getInput('apply-fixes') === 'true',
    commentOnPr: core.getInput('comment-on-pr') !== 'false',
    uploadSarif: core.getInput('upload-sarif') === 'true',
    scoreThreshold: rc?.scoreThreshold ?? parseInt(core.getInput('score-threshold') || '0', 10),
    regressionThreshold: rc?.regressionThreshold ?? parseInt(core.getInput('regression-threshold') || '0', 10),
    failOnNewOnly: rc?.failOnNewOnly ?? core.getInput('fail-on-new-only') === 'true',
    // PRE-954 + PRE-1186 Stage 3B: per-run callback config. .presetrc
    // precedence does NOT apply — these are infrastructure config, not
    // enforcement settings.
    presetApiKey: core.getInput('preset-api-key') || '',
    mcpGatewayUrl: core.getInput('mcp-gateway-url') || 'https://mcp.presetai.dev',
    mcpOidcAudience: core.getInput('mcp-oidc-audience') || 'https://presetai.dev',
    disableCallback: core.getInput('disable-callback') === 'true',
    // PRE-2873: explicit opt-out for the full-mode-with-zero-binding-rules
    // fail condition. Action input only, like applyFixes and disableCallback
    // above: a CI behavior toggle, not a design-system enforcement setting,
    // so .presetrc precedence does not apply.
    allowUnchecked: core.getInput('allow-unchecked') === 'true',
  };
}
