/**
 * Shared types for the Preset GitHub Action (PRE-329).
 */

import { resolveValidationMode } from './gateway-mode.js';

export interface ActionConfig {
  /** GitHub token for PR comments and annotations. */
  githubToken: string;
  /** Supabase project URL (enables full DB validation). */
  supabaseUrl?: string;
  /** Supabase anon key. */
  supabaseKey?: string;
  /** Design system UUID. */
  designSystemId?: string;
  /** Optional layer ID for multi-layer systems. */
  layerId?: string;
  /** Glob patterns for files to include. */
  include: string[];
  /** Glob patterns for files to exclude. */
  exclude: string[];
  /** Fail the check if errors are found. */
  failOnErrors: boolean;
  /** Fail the check if warnings are found. */
  failOnWarnings: boolean;
  /** Run the static composition-conformance checks (PRE-1484 first slice). Default false (opt-in). */
  compositionChecks: boolean;
  /**
   * Auto-apply high-confidence, non-breaking design-system codemods to changed
   * JSX/TSX and commit them back to the PR branch. Default false (opt-in).
   * Requires `permissions: contents: write`; skipped for fork PRs. PRE-1933.
   */
  applyFixes: boolean;
  /** Post/update a PR comment with results. */
  commentOnPr: boolean;
  /** Generate SARIF output file. */
  uploadSarif: boolean;
  /** Minimum health score to pass (0-100, 0 = disabled). PRE-613. */
  scoreThreshold: number;
  /** Max allowed score drop from previous snapshot (0 = disabled). PRE-613. */
  regressionThreshold: number;
  /** Only fail on new violations (not in baseline). PRE-615. */
  failOnNewOnly: boolean;
  /**
   * Preset API key for the per-run callback. Optional fallback for workflows
   * that can't use OIDC (self-hosted runners without id-token: write, or
   * pre-PRE-1186 install setups). Empty + OIDC unavailable = callback skipped.
   * PRE-954 + PRE-1186 Stage 3B.
   */
  presetApiKey: string;
  /**
   * Base URL for the MCP gateway (callback target). PRE-954.
   */
  mcpGatewayUrl: string;
  /**
   * Audience claim requested for the OIDC token mint when running on GitHub
   * Actions. Must match the gateway's `MCP_OIDC_AUDIENCE` secret. Production
   * default is `https://presetai.dev` (the prod Supabase secret value; the
   * doc comment in `supabase/functions/_shared/env.ts` says `preset.dev` but
   * that's stale — verified against the live secret on 2026-05-18).
   * PRE-1186 Stage 3B.
   */
  mcpOidcAudience: string;
  /** Disable the per-run callback regardless of available auth. PRE-954. */
  disableCallback: boolean;
  /**
   * PRE-2873: accept a full-mode run where none of the design system's binding
   * rules applied to any changed file, instead of failing it. Default false:
   * a full-mode run that checked nothing against the customer's own rules is
   * not a compliance pass, and must not exit 0 silently (the original defect).
   * Has no effect in basic mode, which never has a design system to check against.
   */
  allowUnchecked: boolean;
}

export interface ChangedFile {
  path: string;
  content: string;
}

export interface FileViolation {
  path: string;
  violations: ActionViolation[];
}

export interface ActionViolation {
  /** Which check produced this. */
  rule: string;
  /** Human-readable rule name for display. */
  ruleId: string;
  /** What was found in the code. */
  found: string;
  /** Human-readable fix instruction. */
  fix: string;
  /**
   * Severity level. `suggestion` is ADVISORY (PRE-2626/PRE-2665): the rule that
   * produced it is parked at `enforcement_level: 'suggest'`, so it must never
   * gate a check or read as a problem. It was previously coerced to `warning`
   * here, which made `fail-on-warnings` fail a PR on advice.
   */
  severity: 'error' | 'warning' | 'suggestion';
  /** 1-based line number. */
  line?: number;
  /** Suggested replacement code. */
  fixCode?: string;
}

export interface ActionResult {
  /** Whether the check passed (no errors, or below threshold). */
  passed: boolean;
  /** Total files checked. */
  filesChecked: number;
  /** Total violations across all files. */
  totalViolations: number;
  /** Total errors. */
  errors: number;
  /** Total warnings. */
  warnings: number;
  /**
   * Total advisory findings. Counted separately and deliberately excluded from
   * `passed`: no threshold gates on advice.
   */
  suggestions: number;
  /**
   * PRE-2897: files checked against ZERO binding design system rules (none at
   * warn/block applied). Every file when only built-in defaults ran. A run with
   * no findings and unchecked files is not a compliance pass and must not be
   * rendered as one.
   */
  uncheckedFiles: number;
  /**
   * PRE-2873: set by index.ts when the unchecked-files gate itself decided to
   * fail this run (full mode, uncheckedFiles > 0, allow-unchecked not set).
   * Deliberately NOT folded into `passed`: `passed` reflects only the
   * validator's own error/warning thresholds (`validate.ts`'s formula), which
   * `failReasons`' error/warning branch keys on. Conflating the two made that
   * branch misattribute an unrelated error/warning count as a failure reason
   * whenever only this gate fired (Codex review round 2 on PRE-2873). For
   * example, a run with `fail-on-errors: false` that also hit this gate would
   * report "1 error" as part of why it failed, even though fail-on-errors
   * was disabled and that error was never going to block anything on its own.
   * Reporters (comment-markdown.ts) read this field directly instead.
   */
  uncheckedGateFailed?: boolean;
  /**
   * PRE-2873 step 2: gateway full mode could not check this run (no
   * credential, connect/auth failure, design system mismatch, missing
   * capability, exhausted allowance, unreadable result). A failure reason on
   * its own, like `uncheckedGateFailed`: it is never folded into `passed`, and
   * it always fails the step. `allow-unchecked` does not cover it.
   */
  gatewayFailure?: string;
  /** True when gatewayFailure is a design system mismatch (the callback is skipped). */
  gatewayTenantMismatch?: boolean;
  /**
   * PRE-3040: a fork or Dependabot PR with no credential available ran
   * generic checks only (defaults, plus composition checks if enabled),
   * `index.ts` cleared `designSystemId`/`supabaseUrl`/`supabaseKey` before
   * calling `validateFiles` for this run, so `uncheckedFiles` was never
   * incremented for files that were never supposed to be checked against a
   * design system in the first place. The sanctioned exception to "no
   * credential on a full-mode run fails": a fork or Dependabot PR cannot
   * read repository secrets, so it never had a credential to lose. Never
   * folded into `passed`, like `gatewayFailure`/`uncheckedGateFailed`; the
   * unchecked-files gate bypasses on this field instead (unchecked-gate.ts).
   */
  forkGenericOnly?: boolean;
  /** Which reason set `forkGenericOnly` (picks the notice text, fork-detection.ts). */
  forkGenericOnlyReason?: 'fork' | 'dependabot';
  /** Per-file violation details. */
  fileViolations: FileViolation[];
  /** Which validation modes ran. */
  modes: ('defaults' | 'full')[];
  /** Per-rule counts. */
  byRule: Record<string, number>;
  /** Health score results (PRE-613, present when DB mode enabled). */
  healthScore?: HealthScoreResult;
  /** Baseline comparison (PRE-615, present when fail-on-new-only + baseline exist). */
  baselineCompare?: BaselineCompare;
}

/** Baseline comparison data (PRE-615). */
export interface BaselineCompare {
  /** Count of violations NOT in the baseline (new regressions). */
  newViolationCount: number;
  /** Count of violations also in the baseline (legacy). */
  legacyViolationCount: number;
  /** Baseline snapshot ID used for comparison. */
  baselineSnapshotId: string;
}

/** Health score data included in CI results (PRE-613). */
export interface HealthScoreResult {
  /** Overall score 0-100. */
  overall: number;
  /** Per-dimension scores. */
  dimensions: {
    tokenAdoption: number;
    presetAdoption: number;
    accessibility: number;
    consistency: number;
  };
  /** Previous snapshot score (null if no history). */
  previousScore: number | null;
  /** Score delta from previous (negative = regression). */
  delta: number | null;
  /** Whether the score meets the threshold. */
  passesThreshold: boolean;
  /** Whether the regression is within bounds. */
  passesRegression: boolean;
  /** Letter grade A-F. */
  grade: string;
}

/**
 * Full mode = the run validates against the customer's own design system, by
 * either backend: the deprecated direct Supabase read (`legacy`) or the Preset
 * gateway (`gateway`, PRE-2873 step 2). Decided from inputs only; see
 * resolveValidationMode. A configuration error is not full mode: it fails the
 * run before validation.
 */
export function isFullModeEnabled(config: ActionConfig): boolean {
  const d = resolveValidationMode(config);
  return d.ok && d.mode !== 'basic';
}
