    ComponentApiProvider = class {
      components;
      constructor(options = {}) {
        if (options.customComponents && !options.includeDefaults) {
          this.components = options.customComponents;
        } else if (options.customComponents && options.includeDefaults) {
          this.components = { ...defaultComponentDefinitions, ...options.customComponents };
        } else {
          this.components = defaultComponentDefinitions;
        }
      }
      /**
       * Normalize component name to lowercase
       */
      normalizeComponentName(name) {
        return name.toLowerCase().replace(/\s+/g, "");
      }
      /**
       * Format props as TypeScript interface
       */
      formatAsTypeScript(props, componentName) {
        const propsInterface = props.map((prop) => {
          const optional = prop.required ? "" : "?";
          return `  /** ${prop.description} */
  ${prop.name}${optional}: ${prop.type};`;
        }).join("\n\n");
        return `interface ${this.capitalize(componentName)}Props {
${propsInterface}
}`;
      }
      /**
       * Format props as JSON Schema
       */
      formatAsJsonSchema(props, componentName) {
        const properties = {};
        const required = [];
        for (const prop of props) {
          const propSchema = {
            description: prop.description
          };
          if (prop.allowedValues) {
            propSchema.enum = prop.allowedValues;
          } else if (prop.type === "boolean") {
            propSchema.type = "boolean";
          } else if (prop.type === "number") {
            propSchema.type = "number";
          } else if (prop.type === "string") {
            propSchema.type = "string";
          } else {
            propSchema.type = "string";
            propSchema.tsType = prop.type;
          }
          if (prop.default) {
            propSchema.default = prop.default;
          }
          properties[prop.name] = propSchema;
          if (prop.required) {
            required.push(prop.name);
          }
        }
        return {
          $schema: "http://json-schema.org/draft-07/schema#",
          title: `${this.capitalize(componentName)}Props`,
          type: "object",
          properties,
          required: required.length > 0 ? required : void 0
        };
      }
      /**
       * Format props as Markdown documentation
       */
      formatAsMarkdown(component, componentName, includeExamples) {
        let md = `# ${this.capitalize(componentName)}

`;
        md += `${component.description}

`;
        md += `## Import

\`\`\`tsx
import { ${this.capitalize(componentName)} } from '${component.importPath}';
\`\`\`

`;
        md += `## Props

`;
        md += `| Prop | Type | Required | Default | Description |
`;
        md += `|------|------|----------|---------|-------------|
`;
        for (const prop of component.props) {
          const required = prop.required ? "Yes" : "No";
          const defaultVal = prop.default ?? "-";
          const escapedType = prop.type.replace(/\|/g, "\\|");
          md += `| \`${prop.name}\` | \`${escapedType}\` | ${required} | ${defaultVal} | ${prop.description} |
`;
        }
        md += `
## Presets

`;
        for (const preset of component.presets) {
          md += `### ${preset.name}

`;
          md += `${preset.description}

`;
          md += `\`\`\`tsx
<${this.capitalize(componentName)} preset="${preset.name}" />
\`\`\`

`;
        }
        if (includeExamples && component.examples.length > 0) {
          md += `## Examples

`;
          for (const example of component.examples) {
            md += `### ${example.title}

`;
            md += `${example.description}

`;
            md += `\`\`\`tsx
${example.code}
\`\`\`

`;
          }
        }
        if (component.relatedComponents.length > 0) {
          md += `## Related Components

`;
          md += component.relatedComponents.map((c2) => `- ${this.capitalize(c2)}`).join("\n");
          md += "\n";
        }
        return md;
      }
      capitalize(str) {
        return str.charAt(0).toUpperCase() + str.slice(1);
      }
      /**
       * Get the full API for a component
       */
      getComponentApi(input) {
        const normalizedName = this.normalizeComponentName(input.component);
        const component = this.components[normalizedName];
        if (!component) {
          return null;
        }
        const format = input.format ?? "typescript";
        const includeExamples = input.includeExamples ?? false;
        const result = {
          component: normalizedName,
          description: component.description,
          props: component.props,
          presets: component.presets,
          commonMistakes: component.commonMistakes ?? [],
          guidance: component.guidance ?? "",
          relatedComponents: component.relatedComponents,
          importStatement: `import { ${this.capitalize(normalizedName)} } from '${component.importPath}';`,
          format
        };
        if (includeExamples) {
          result.examples = component.examples;
        }
        return result;
      }
      /**
       * Get formatted API documentation
       */
      getFormattedApi(input) {
        const normalizedName = this.normalizeComponentName(input.component);
        const component = this.components[normalizedName];
        if (!component) {
          return null;
        }
        const format = input.format ?? "typescript";
        const includeExamples = input.includeExamples ?? false;
        switch (format) {
          case "typescript":
            return this.formatAsTypeScript(component.props, normalizedName);
          case "json-schema":
            return this.formatAsJsonSchema(component.props, normalizedName);
          case "markdown":
            return this.formatAsMarkdown(component, normalizedName, includeExamples);
          default:
            return this.formatAsTypeScript(component.props, normalizedName);
        }
      }
      /**
       * List all available components
       */
      listComponents() {
        return Object.keys(this.components);
      }
      /**
       * Check if a component exists
       */
      hasComponent(name) {
        return this.normalizeComponentName(name) in this.components;
      }
    };
