  if (label.toLowerCase().includes("save")) label = "Save";
  if (label.toLowerCase().includes("cancel")) label = "Cancel";
  if (label.toLowerCase().includes("submit")) label = "Submit";
  if (label.toLowerCase().includes("create")) label = "Create";
  if (label.toLowerCase().includes("edit")) label = "Edit";
