/**
 * Preset Design System Check — GitHub Action entry point (PRE-329).
 *
 * Validates PR code against design system rules using two modes:
 * - Defaults: @preset/core patterns (always, no credentials needed)
 * - Full: DesignSystemValidator from @preset/mcp (when DB credentials provided)
 */

import * as core from '@actions/core';
import * as github from '@actions/github';
import { parseConfig } from './config.js';
import { getChangedFiles } from './changed-files.js';
import { validateFiles } from './validate.js';
import { createAnnotations } from './annotations.js';
import { postOrUpdateComment } from './comment.js';
import { writeSarif } from './sarif.js';
import type { ActionConfig, ActionResult } from './types.js';
import { runHealthScore } from './health-score.js';
import { fireAgentEventsCallback } from './agent-events-callback.js';
import { applyFixes } from './apply-fixes.js';
import { evaluateUncheckedGate } from './unchecked-gate.js';
import { resolveValidationMode } from './gateway-mode.js';
import { connectGateway, credentialAvailable, GatewayFailure, type GatewayConnection } from './gateway-client.js';
import {
  forkOrDependabotNotice,
  forkOrDependabotReason,
  buildForkContext,
  resolveForkGenericOnly,
  buildValidateConfig,
  commentFailureLogLevel,
  type ForkGenericOnly,
  type RawPullRequestPayload,
} from './fork-detection.js';

async function run(): Promise<void> {
  const startTime = Date.now();

  // 1. Parse configuration
  const config = parseConfig();

  // PRE-2873 step 2: the validation mode comes from the configured inputs only
  // (gateway-mode.ts). Half a Supabase pair used to run basic mode silently.
  const decision = resolveValidationMode(config);
  if (!decision.ok) {
    // Every failure path sets `passed`, so a workflow reading the output sees
    // false rather than an empty string (Codex, #2643 round 3).
    core.setOutput('passed', false);
    core.setFailed(`Design system check misconfigured: ${decision.error}`);
    return;
  }
  const mode = decision.mode;

  const healthEnabled = config.scoreThreshold > 0 || config.regressionThreshold > 0;
  const fullLabel = mode === 'gateway' ? ' + full (preset AI gateway)' : mode === 'legacy' ? ' + full (direct Supabase, deprecated)' : '';

  // PRE-3040: a fork or Dependabot PR cannot read repository secrets, so a
  // missing credential there is not the customer's misconfiguration: it is
  // what forks and Dependabot always look like. Decided from inputs only,
  // same discipline as resolveValidationMode: the mode table's other rows
  // (same-repo PR or any non-PR event with no credential) are UNCHANGED:
  // they still hard-fail via preflightFailure below, because `reason` is
  // null for them and the carve-out never applies.
  //
  // PRE-3042: decided BEFORE the "Modes:" line below (not after, as PRE-3040
  // left it) so that line never claims full mode on a run that is about to
  // be downgraded to generic-only. Moving only the DECISION up, not the
  // gateway-connect attempt itself, keeps every other log line (including
  // the per-mode ordering) identical for a non-fork run: `oidcAvailable` is
  // captured once here and reused below for the connectGateway() path.
  let forkGenericOnly: ForkGenericOnly | null = null;
  const oidcAvailable = () =>
    Boolean(process.env.ACTIONS_ID_TOKEN_REQUEST_URL && process.env.ACTIONS_ID_TOKEN_REQUEST_TOKEN);
  if (mode === 'gateway') {
    const prPayload = github.context.payload.pull_request as RawPullRequestPayload | undefined;
    const ctx = buildForkContext(github.context.eventName, prPayload);
    // `github.context.repo` throws when GITHUB_REPOSITORY is unset and the
    // event payload carries no `repository` either (always set on a real
    // GitHub Actions runner; absent only for a direct, non-Actions
    // invocation, e.g. the dist smoke tests). Read the env var directly so a
    // run with no repo context still falls through to today's unchanged
    // behavior (reason stays null) instead of crashing.
    const baseRepoFullName = process.env.GITHUB_REPOSITORY;
    const reason = baseRepoFullName ? forkOrDependabotReason(ctx, baseRepoFullName) : null;
    const noCredential = !credentialAvailable(config, oidcAvailable);
    forkGenericOnly = resolveForkGenericOnly(reason, noCredential);
  }

  // PRE-3042: a fork/Dependabot generic-only run never claims "full" here;
  // it is about to be checked against generic rules only, decided above.
  const effectiveFullLabel = forkGenericOnly ? '' : fullLabel;
  core.info('Preset Design System Check');
  core.info(`  Modes: defaults${effectiveFullLabel}${healthEnabled ? ' + health' : ''}`);
  core.info(`  Include: ${config.include.join(', ')}`);
  core.info(`  Exclude: ${config.exclude.join(', ')}`);
  if (mode === 'legacy') {
    core.warning(
      'supabase-url and supabase-key are deprecated for validation. An anonymous key cannot read a private ' +
        'design system, so full mode checks nothing against it. Remove both inputs and grant the job ' +
        '`permissions: id-token: write` (with the preset AI GitHub App installed) to validate through the preset AI gateway.',
    );
  }

  // PRE-2873 step 2: in gateway mode the preflight (credential, connect, bound
  // design system, validate_code in the catalog) runs BEFORE the zero-file
  // return, so a misconfigured run fails even when nothing relevant changed.
  let gateway: GatewayConnection | null = null;
  let preflightFailure: GatewayFailure | null = null;
  if (mode === 'gateway') {
    if (forkGenericOnly) {
      core.info(forkOrDependabotNotice(forkGenericOnly.reason));
    } else {
      try {
        gateway = await connectGateway(config, {
          fetch: globalThis.fetch,
          mintIdToken: (audience) => core.getIDToken(audience),
          oidcAvailable,
          sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
          log: (msg) => core.info(msg),
        });
        core.info(
          `  Gateway: bound to ${gateway.boundLabel ?? gateway.boundDesignSystemId} via ${gateway.credentialSource === 'oidc' ? 'GitHub OIDC' : 'preset-api-key'}`,
        );
      } catch (err) {
        if (!(err instanceof GatewayFailure)) throw err;
        preflightFailure = err;
      }
    }
  }

  try {
    await runChecks(config, startTime, gateway, preflightFailure, forkGenericOnly);
  } finally {
    // A connected client holds a standalone SSE stream that can keep the
    // process alive; close it on every path.
    if (gateway) await gateway.close();
  }
}

async function runChecks(
  config: ActionConfig,
  startTime: number,
  gateway: GatewayConnection | null,
  preflightFailure: GatewayFailure | null,
  forkGenericOnly: ForkGenericOnly | null,
): Promise<void> {
  // 2. Get changed files from PR
  const files = await getChangedFiles(config);
  if (files.length === 0 && !preflightFailure) {
    core.info('No design-system-relevant files changed. Skipping validation.');
    core.setOutput('violations-count', 0);
    core.setOutput('errors-count', 0);
    core.setOutput('warnings-count', 0);
    core.setOutput('health-score', '');
    core.setOutput('passed', true);
    core.setOutput('unchecked-files', 0);
    // PRE-954: still fire the callback so the dashboard sees every run.
    // A no-op invocation is a meaningful signal — the Action ran, just
    // had nothing to check. outcome:pass + filesChecked:0 is the
    // canonical "no-op run" shape.
    const noopResult: ActionResult = {
      passed: true,
      filesChecked: 0,
      totalViolations: 0,
      errors: 0,
      suggestions: 0,
      uncheckedFiles: 0,
      warnings: 0,
      fileViolations: [],
      modes: ['defaults'],
      byRule: {},
      // PRE-3042: carry the generic-only decision onto the no-op result too,
      // so a fork/Dependabot PR that changes no relevant files logs the
      // callback's no-auth skip as info, the same as one that does.
      ...(forkGenericOnly ? { forkGenericOnly: true, forkGenericOnlyReason: forkGenericOnly.reason } : {}),
    };
    await fireAgentEventsCallback(config, noopResult, startTime, 0);
    return;
  }

  // 3. Validate all files. PRE-3040: a fork/Dependabot generic-only run
  // clears the design-system fields before calling validateFiles, for THIS
  // call only, so resolveValidationMode inside it genuinely resolves
  // 'basic' and uncheckedFiles is never incremented for files that were
  // never supposed to be checked against a design system in the first
  // place. `gateway` is already null on this path (connectGateway was never
  // called), and the ORIGINAL `config` (with designSystemId still set) is
  // used everywhere else below, including evaluateUncheckedGate.
  const validateConfig: ActionConfig = buildValidateConfig(config, forkGenericOnly);
  const result = await validateFiles(files, validateConfig, gateway);
  if (preflightFailure) {
    result.gatewayFailure = preflightFailure.message;
    result.gatewayTenantMismatch = preflightFailure.tenantMismatch;
  }
  if (forkGenericOnly) {
    result.forkGenericOnly = true;
    result.forkGenericOnlyReason = forkGenericOnly.reason;
  }

  core.info(`Checked ${result.filesChecked} files: ${result.errors} errors, ${result.warnings} warnings`);

  // 3b. PRE-2873: full mode configured, but none of the design system's own
  // binding rules applied to one or more changed files. Decided here, before
  // annotations/comment/outputs are built (Codex round 1: computing this only
  // inside the failReasons block left the `passed` output and the PR comment
  // badge saying "passed" for a run whose check step was about to exit
  // non-zero). Recorded on `result.uncheckedGateFailed`, deliberately NOT
  // folded into `result.passed` itself (Codex round 2: mutating `passed`
  // made the error/warning failReasons branch below misattribute an
  // unrelated error/warning count to this gate on a run where, say,
  // fail-on-errors is disabled). A full-mode run that checked nothing
  // against the customer's own rules is not a compliance pass and must not
  // report as one anywhere, which is the defect this ticket fixes: PRE-2897
  // added the unchecked-files output and nothing read it.
  const uncheckedGate = evaluateUncheckedGate(config, result);
  result.uncheckedGateFailed = uncheckedGate.shouldFail;
  // PRE-2873 step 2: a gateway failure is its own fail reason, decided here
  // with the unchecked gate so the comment and the `passed` output below
  // already agree with the step's exit code.
  if (result.gatewayFailure) core.error(`preset AI gateway: ${result.gatewayFailure}`);

  // 4. Run health scoring (PRE-613)
  const healthScore = await runHealthScore(config, files.map(f => f.path));
  if (healthScore) {
    result.healthScore = healthScore;
    core.info(`Health: ${healthScore.overall}/100 (${healthScore.grade})${healthScore.delta !== null ? ` Δ${healthScore.delta >= 0 ? '+' : ''}${healthScore.delta}` : ''}`);
  }

  // 4b. Baseline comparison (PRE-615)
  // TODO: baseline compare requires a saved snapshot ID — future enhancement
  // For now, fail-on-new-only modifies the pass/fail logic below

  // 5. Create annotations (inline on PR diff)
  createAnnotations(result);

  // 6. Post/update PR comment
  // PRE-3042: always attempt; only a generic-only `pull_request` run's
  // read-only-token 403 logs as info, see commentFailureLogLevel. Every
  // other failure, and every failure on a same-repo run, is still a warning.
  if (config.commentOnPr) {
    try {
      await postOrUpdateComment(result, config);
    } catch (e) {
      if (commentFailureLogLevel(forkGenericOnly, github.context.eventName, e) === 'info') {
        core.info(`PR comment not posted: this run's token can't write to the pull request (${e}). The notice above is the result.`);
      } else {
        core.warning(`Failed to post PR comment: ${e}`);
      }
    }
  }

  // 7. Generate SARIF file
  if (config.uploadSarif && result.totalViolations > 0) {
    const sarifPath = writeSarif(result);
    core.info(`SARIF output written to ${sarifPath}`);
  }

  // 7b. PRE-1933: optional autofix — apply high-confidence, non-breaking
  // codemods to changed files and commit them back to the PR branch. The
  // committed count seeds the validate_fix activation producer via the callback.
  // Failure here never fails the Action.
  let fixesApplied = 0;
  let rulesApplied: string[] = [];
  if (config.applyFixes) {
    try {
      const fix = await applyFixes(files, config);
      fixesApplied = fix.fixesApplied;
      rulesApplied = fix.rulesApplied;
    } catch (e) {
      core.warning(`apply-fixes failed: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  core.setOutput('fixes-applied', fixesApplied);

  // 8. Set outputs
  core.setOutput('violations-count', result.totalViolations);
  core.setOutput('errors-count', result.errors);
  core.setOutput('warnings-count', result.warnings);
  core.setOutput('health-score', healthScore?.overall ?? '');
  core.setOutput('health-grade', healthScore?.grade ?? '');
  core.setOutput('health-delta', healthScore?.delta ?? '');
  // PRE-2873: the overall `passed` output must agree with whether the step
  // is about to exit non-zero, which depends on BOTH the validator's own
  // threshold result and the unchecked-files gate below.
  core.setOutput('passed', result.passed && !result.uncheckedGateFailed && !result.gatewayFailure);
  core.setOutput('unchecked-files', result.uncheckedFiles);

  // 9. Fail if thresholds exceeded
  const failReasons: string[] = [];

  if (config.failOnNewOnly && result.baselineCompare) {
    // PRE-615: Only fail on NEW violations (not in baseline)
    if (result.baselineCompare.newViolationCount > 0) {
      failReasons.push(`${result.baselineCompare.newViolationCount} new violation${result.baselineCompare.newViolationCount !== 1 ? 's' : ''} since baseline`);
    }
    // Legacy violations are reported but don't block
    if (result.baselineCompare.legacyViolationCount > 0) {
      core.info(`${result.baselineCompare.legacyViolationCount} legacy violations (not blocking)`);
    }
  } else if (!result.passed) {
    if (result.errors > 0) failReasons.push(`${result.errors} error${result.errors !== 1 ? 's' : ''}`);
    if (config.failOnWarnings && result.warnings > 0) {
      failReasons.push(`${result.warnings} warning${result.warnings !== 1 ? 's' : ''}`);
    }
  }

  if (healthScore && !healthScore.passesThreshold) {
    failReasons.push(`health score ${healthScore.overall} < ${config.scoreThreshold}`);
  }
  if (healthScore && !healthScore.passesRegression) {
    failReasons.push(`score dropped ${Math.abs(healthScore.delta!)}pts (max ${config.regressionThreshold})`);
  }

  // PRE-2873: the gate itself was already decided in step 3b (so the `passed`
  // output and the PR comment, both built above, already agree with this via
  // `result.uncheckedGateFailed`). Reused here only to push the warning and
  // the failReasons phrase that actually fails the step (core.setFailed below).
  if (uncheckedGate.shouldFail) {
    core.warning(uncheckedGate.warningMessage!);
    failReasons.push(uncheckedGate.failReason!);
  }
  if (result.gatewayFailure) {
    failReasons.push('the preset AI gateway could not check this run (see the error above)');
  }

  if (failReasons.length > 0) {
    core.setFailed(`Design system check failed: ${failReasons.join(', ')}`);
  }

  // 10. PRE-954: per-run callback to Preset's agent_validation_outcome
  // endpoint. Fire-and-forget — failure to deliver MUST NOT fail the Action.
  // Disabled when preset-api-key is unset OR disable-callback is true.
  // PRE-1933: carries the committed-autofix count so the gateway can emit the
  // validate_fix activation outcome.
  await fireAgentEventsCallback(config, result, startTime, failReasons.length, fixesApplied, rulesApplied);
}

run().catch(e => {
  core.setFailed(`Unexpected error: ${e instanceof Error ? e.message : String(e)}`);
});
