/**
 * PRE-954 + PRE-1186 Stage 3B: per-run callback to Preset's
 * agent_validation_outcome endpoint.
 *
 * Fire-and-forget POST after each Action run, capturing override flags +
 * .presetrc state for bypass-detection (PRE-943 §4 T1 + T8). Failure to
 * deliver MUST NOT fail the Action — this is an observability surface, not
 * a critical path.
 *
 * Auth (PRE-1186 Stage 3B): prefer GitHub Actions OIDC. Workflows that grant
 * `permissions: id-token: write` and have installed the preset AI GitHub App
 * authenticate without any secret in repo settings. Falls back to the legacy
 * `preset-api-key` input when OIDC is unavailable (self-hosted runner without
 * id-token permission, or pre-PRE-1186 installs still on the API-key path).
 *
 * Disabled when:
 *   - `disable-callback: true` action input set (per-run opt-out)
 *   - Both OIDC mint AND api-key are unavailable (graceful degradation)
 *
 * .presetrc handling: client-side filter to the 7-field allowlist before
 * sending. Server filters again as defense-in-depth (PRE-943 T8 privacy
 * boundary). Customers know exactly what gets reported because we filter
 * twice and document it.
 */

import * as core from '@actions/core';
import * as github from '@actions/github';
import type { ActionConfig, ActionResult } from './types.js';
import { loadPresetRc } from './config.js';

import {
  buildAgentEventPayload,
  deriveOutcome,
  describeCallbackFailure,
  filterPresetRc,
  noAuthLogLevel,
  resolveAuthHeader,
} from './agent-events-callback-helpers.js';

// Re-export so any existing import from this module's prior public surface
// continues to work, and so the M2 reviewer's mental model ("these helpers
// live with the callback") stays intact at the file boundary.
export { deriveOutcome, filterPresetRc };

const CALLBACK_TIMEOUT_MS = 3000;

// Pure helpers (deriveOutcome, filterPresetRc, buildAgentEventPayload) live
// in ./agent-events-callback-helpers.ts so tests can import them without
// pulling @actions/core + @actions/github (which would force a workspace
// install in the test environment). Mirrors the server-side
// agent-events-helpers.ts split. This module's own job, below, is only the
// @actions/github context reads and the actual network I/O.

/**
 * Fire the callback. Returns a Promise that resolves regardless of success
 * (so the caller can `await` without risk of throwing). Logs warnings on
 * failure but never re-throws.
 */
export async function fireAgentEventsCallback(
  config: ActionConfig,
  result: ActionResult,
  startTime: number,
  failReasonsLength: number,
  // PRE-1933: committed-autofix telemetry. Default 0 / [] so the no-op and
  // pre-autofix call sites keep their existing 4-arg shape.
  fixesApplied = 0,
  rulesApplied: string[] = [],
): Promise<void> {
  // Guard: callback opt-out paths
  if (config.disableCallback) {
    core.debug('[preset-callback] disabled via disable-callback input');
    return;
  }
  // PRE-2873 step 2: on a design system mismatch the server would refuse the
  // configured id this payload carries, so the step's own failure is the record.
  if (result.gatewayTenantMismatch) {
    core.warning('[preset-callback] skipped: design-system-id does not match the credential\'s design system');
    return;
  }
  // PRE-1186 Stage 3B: resolve auth (OIDC preferred, api-key fallback). When
  // both are unavailable, the callback is skipped — same graceful-degradation
  // contract as the pre-OIDC code.
  const { resolved: auth, lastError: authError } = await resolveAuthHeader(
    config,
    (audience) => core.getIDToken(audience),
  );
  if (!auth) {
    const oidcDetail = authError ? ` (OIDC: ${authError})` : '';
    // PRE-3042: `noAuthLogLevel` decides info vs. warning (see its own
    // doc comment, agent-events-callback-helpers.ts). The info copy is its
    // own: the warning's setup advice is impossible on a fork or Dependabot
    // run, and it must not call itself a warning.
    if (noAuthLogLevel(result, github.context.eventName) === 'info') {
      core.info(
        `[preset-callback] no auth available on this fork or Dependabot run; skipping callback${oidcDetail}. ` +
          "This is expected: forks and Dependabot can't read repository secrets, so this run sends no signal to your Sentinel inbox.",
      );
    } else {
      const message =
        `[preset-callback] no auth available; skipping callback${oidcDetail}. ` +
        'Your Sentinel inbox will not receive signal from this Action. ' +
        'Recommended: install the preset AI GitHub App and set `permissions: id-token: write` on the workflow for OIDC auth. ' +
        'Fallback: issue an API key at https://app.presetai.dev/connect and pass it as `preset-api-key:`. ' +
        'To suppress this warning, set `disable-callback: true`.';
      core.warning(message);
    }
    return;
  }
  core.debug(`[preset-callback] auth source: ${auth.source}`);
  if (!config.designSystemId) {
    core.debug('[preset-callback] design-system-id not set; skipping callback');
    return;
  }

  // Build payload from GitHub Actions context
  const ctx = github.context;
  const repo = `${ctx.repo.owner}/${ctx.repo.repo}`;
  const runId = String(ctx.runId);
  // GitHub exposes GITHUB_RUN_ATTEMPT as env var (string "1", "2", ...).
  // @actions/github context does NOT expose it as a typed property, so we
  // read the env var directly. Default to 1 (pre-rerun behavior) if unset.
  const runAttempt = parseInt(process.env.GITHUB_RUN_ATTEMPT || '1', 10) || 1;

  const presetrc = loadPresetRc();

  // PRE-3040 review (finding #6): the payload, including `action_version`,
  // is built by the pure `buildAgentEventPayload` (agent-events-callback-
  // helpers.ts) so it is proven by a real executed test reading the BUILT
  // object, not only by this module re-stating the `ACTION_VERSION` import.
  // Everything passed in here is an @actions/github context read or an
  // argument this function already received; the helper itself has no
  // @actions/* import.
  const payload = buildAgentEventPayload({
    config,
    result,
    failReasonsLength,
    fixesApplied,
    rulesApplied,
    startTime,
    now: Date.now(),
    presetrc,
    repo,
    runId,
    runAttempt,
    checkRunId: ctx.payload?.check_run?.id ? String(ctx.payload.check_run.id) : undefined,
    commitSha: ctx.sha || undefined,
    commitAuthorId: ctx.actor || undefined,
    // PRE-1418: PR identity (PR triggers carry pull_request; fall back to the
    // pushed ref for push triggers).
    prNumber: ctx.payload?.pull_request?.number ?? undefined,
    branch:
      (ctx.payload?.pull_request?.head?.ref as string | undefined) ??
      (ctx.ref ? ctx.ref.replace(/^refs\/heads\//, '') : undefined),
  });

  // Endpoint: /v1/agent-events under the gateway
  const url = `${config.mcpGatewayUrl.replace(/\/$/, '')}/v1/agent-events`;

  // Fire-and-forget with timeout. Errors are warnings only.
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), CALLBACK_TIMEOUT_MS);

  try {
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': auth.header,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
      signal: controller.signal,
    });
    clearTimeout(timeoutId);

    if (!response.ok) {
      const text = await response.text().catch(() => '');
      core.warning(`[preset-callback] ${describeCallbackFailure(response.status, text)}`);
      return;
    }

    const body = await response.json().catch(() => null) as { id?: string; already_recorded?: boolean } | null;
    if (body?.already_recorded) {
      core.debug(`[preset-callback] already recorded (id=${body.id})`);
    } else {
      core.debug(`[preset-callback] recorded (id=${body?.id})`);
    }
  } catch (err) {
    clearTimeout(timeoutId);
    if ((err as Error).name === 'AbortError') {
      core.warning(`[preset-callback] timeout after ${CALLBACK_TIMEOUT_MS}ms`);
    } else {
      core.warning(`[preset-callback] failed: ${(err as Error).message}`);
    }
  }
}
