var TenantService = class {
  constructor(client) {
    this.client = client;
  }
  // --------------------------------------------------------------------------
  // CONTEXT RESOLUTION
  // --------------------------------------------------------------------------
  /**
   * Resolve tenant context from slug
   * Returns null if user doesn't have access to the organization
   */
  async resolveTenantBySlug(slug) {
    const { data: orgData, error: orgError } = await this.client.from("organizations").select("id, name, slug").eq("slug", slug).single();
    if (orgError || !orgData) return null;
    const org = orgData;
    const { data: user } = await this.client.auth.getUser();
    if (!user.user) return null;
    const { data: memberData, error: memberError } = await this.client.from("organization_members").select("role").eq("organization_id", org.id).eq("user_id", user.user.id).single();
    if (memberError || !memberData) return null;
    const member = memberData;
    return {
      organizationId: org.id,
      organizationSlug: org.slug,
      organizationName: org.name,
      userId: user.user.id,
      userRole: member.role
    };
  }
  /**
   * Resolve tenant context from organization ID
   */
  async resolveTenantById(organizationId) {
    const { data: orgData, error: orgError } = await this.client.from("organizations").select("id, name, slug").eq("id", organizationId).single();
    if (orgError || !orgData) return null;
    const org = orgData;
    const { data: user } = await this.client.auth.getUser();
    if (!user.user) return null;
    const { data: memberData, error: memberError } = await this.client.from("organization_members").select("role").eq("organization_id", org.id).eq("user_id", user.user.id).single();
    if (memberError || !memberData) return null;
    const member = memberData;
    return {
      organizationId: org.id,
      organizationSlug: org.slug,
      organizationName: org.name,
      userId: user.user.id,
      userRole: member.role
    };
  }
  /**
   * Get all organizations the current user belongs to
   */
  async getUserOrganizations() {
    const { data, error } = await this.client.from("organizations").select("*").order("name");
    if (error || !data) return [];
    return data.map((org) => ({
      id: org.id,
      name: org.name,
      slug: org.slug,
      createdAt: new Date(org.created_at),
      updatedAt: new Date(org.updated_at)
    }));
  }
  // --------------------------------------------------------------------------
  // ORGANIZATION CRUD
  // --------------------------------------------------------------------------
  /**
   * Create a new organization
   * The creating user automatically becomes an admin
   */
  async createOrganization(input) {
    const { data: user } = await this.client.auth.getUser();
    if (!user.user) return null;
    const { data: orgData, error: orgError } = await this.client.from("organizations").insert({
      name: input.name,
      slug: input.slug
    }).select().single();
    if (orgError || !orgData) return null;
    const org = orgData;
    const { error: memberError } = await this.client.from("organization_members").insert({
      organization_id: org.id,
      user_id: user.user.id,
      role: "admin"
    });
    if (memberError) {
      await this.client.from("organizations").delete().eq("id", org.id);
      return null;
    }
    return {
      id: org.id,
      name: org.name,
      slug: org.slug,
      createdAt: new Date(org.created_at),
      updatedAt: new Date(org.updated_at)
    };
  }
  /**
   * Update an organization (admin only)
   */
  async updateOrganization(organizationId, input) {
    const { data: rawData, error } = await this.client.from("organizations").update({
      ...input.name && { name: input.name },
      ...input.slug && { slug: input.slug }
    }).eq("id", organizationId).select().single();
    if (error || !rawData) return null;
    const data = rawData;
    return {
      id: data.id,
      name: data.name,
      slug: data.slug,
      createdAt: new Date(data.created_at),
      updatedAt: new Date(data.updated_at)
    };
  }
  /**
   * Delete an organization (admin only)
   * This cascades to all related data
   */
  async deleteOrganization(organizationId) {
    const { error } = await this.client.from("organizations").delete().eq("id", organizationId);
    return !error;
  }
  // --------------------------------------------------------------------------
  // MEMBER MANAGEMENT
  // --------------------------------------------------------------------------
  /**
   * Get all members of an organization
   */
  async getOrganizationMembers(organizationId) {
    const { data, error } = await this.client.from("organization_members").select("*").eq("organization_id", organizationId).order("created_at");
    if (error || !data) return [];
    return data.map((m) => ({
      id: m.id,
      organizationId: m.organization_id,
      userId: m.user_id,
      role: m.role,
      createdAt: new Date(m.created_at),
      updatedAt: new Date(m.updated_at)
    }));
  }
  /**
   * Add a member to an organization (admin only)
   *
   * Defaults to editor — flat Founder cohort means added members get write
   * access (PRE-1683); pass 'viewer' explicitly for read-only.
   */
  async addMember(organizationId, userId, role = "editor") {
    const { data: rawData, error } = await this.client.from("organization_members").insert({
      organization_id: organizationId,
      user_id: userId,
      role
    }).select().single();
    if (error || !rawData) return null;
    const data = rawData;
    return {
      id: data.id,
      organizationId: data.organization_id,
      userId: data.user_id,
      role: data.role,
      createdAt: new Date(data.created_at),
      updatedAt: new Date(data.updated_at)
    };
  }
  /**
   * Update a member's role (admin only)
   */
  async updateMemberRole(organizationId, userId, role) {
    const { error } = await this.client.from("organization_members").update({ role }).eq("organization_id", organizationId).eq("user_id", userId);
    return !error;
  }
  /**
   * Remove a member from an organization (admin only)
   */
  async removeMember(organizationId, userId) {
    const { error } = await this.client.from("organization_members").delete().eq("organization_id", organizationId).eq("user_id", userId);
    return !error;
  }
  /**
   * Check if user has at least the specified role
   */
  async hasRole(organizationId, requiredRole) {
    const { data: user } = await this.client.auth.getUser();
    if (!user.user) return false;
    const { data: memberData } = await this.client.from("organization_members").select("role").eq("organization_id", organizationId).eq("user_id", user.user.id).single();
    if (!memberData) return false;
    const member = memberData;
    const roleHierarchy = {
      admin: 3,
      editor: 2,
      viewer: 1
    };
    const userLevel = roleHierarchy[member.role];
    const requiredLevel = roleHierarchy[requiredRole];
    return (userLevel ?? 0) >= (requiredLevel ?? 0);
  }
};
function createTenantService(client) {
  return new TenantService(client);
}

