/**
 * Health scoring integration for CI (PRE-613).
 *
 * Runs the ScoringEngine against the design system and compares
 * against the previous snapshot for regression detection.
 */

import * as core from '@actions/core';
import { createClient as createSupabaseClient } from '@preset/db';
import {
  ScoringEngine,
  typographyModule,
  colorModule,
  adoptionModule,
  consistencyModule,
  complianceModule,
  fragmentationModule,
  deadArtifactsModule,
  duplicationModule,
  aiReadinessModule,
  resolveConfig,
} from '@preset/health';
import { readTokenValue } from '@preset/core';
import type { ActionConfig, HealthScoreResult, BaselineCompare } from './types.js';

// =============================================================================
// Score to Grade
// =============================================================================

function scoreToGrade(score: number): string {
  if (score >= 90) return 'A';
  if (score >= 75) return 'B';
  if (score >= 50) return 'C';
  if (score >= 25) return 'D';
  return 'F';
}

// =============================================================================
// Run Health Score
// =============================================================================

/**
 * Run health scoring against the design system and check thresholds.
 * Returns null if DB credentials are not configured.
 */
export async function runHealthScore(
  config: ActionConfig,
  changedFiles: string[],
): Promise<HealthScoreResult | null> {
  if (!config.supabaseUrl || !config.supabaseKey || !config.designSystemId) {
    return null;
  }

  // Skip if both thresholds are disabled
  if (config.scoreThreshold <= 0 && config.regressionThreshold <= 0) {
    return null;
  }

  core.info('Running health score...');

  const supabase = createSupabaseClient(config.supabaseUrl, config.supabaseKey);

  // 1. Fetch design system config (tokens, presets, etc.)
  const [tokensResult, dsResult] = await Promise.all([
    supabase
      .from('design_tokens')
      .select('name, category, value, metadata')
      .eq('design_system_id', config.designSystemId),
    supabase
      .from('design_systems')
      .select('name')
      .eq('id', config.designSystemId)
      .single(),
  ]);

  if (tokensResult.error) {
    core.warning(`Failed to fetch tokens: ${tokensResult.error.message}`);
    return null;
  }

  if (dsResult.error) {
    core.warning(`Failed to fetch design system: ${dsResult.error.message}`);
    return null;
  }

  const dsName = dsResult.data?.name ?? 'unknown';

  // Fetch scoring_config separately (column may not be in generated types yet)
  let rawScoringConfig: Record<string, unknown> | null = null;
  try {
    const { data } = await supabase
      .from('design_systems')
      .select('scoring_config')
      .eq('id', config.designSystemId!)
      .single() as { data: { scoring_config: Record<string, unknown> | null } | null; error: unknown };
    if (data?.scoring_config) rawScoringConfig = data.scoring_config;
  } catch {
    core.debug('Could not fetch scoring config, using defaults');
  }

  // 2. Build typography config from tokens
  const typographyConfig = tokensToTypographyConfig(
    (tokensResult.data || []) as unknown as TokenRow[],
  );

  // 3. Run scoring engine
  const engine = new ScoringEngine();
  engine.registerAll([
    typographyModule,
    colorModule,
    adoptionModule,
    consistencyModule,
    complianceModule,
    fragmentationModule,
    deadArtifactsModule,
    duplicationModule,
    aiReadinessModule,
  ]);

  const scoringConfig = rawScoringConfig
    ? {
        weights: (rawScoringConfig.weights as Record<string, number> | undefined) as Parameters<typeof resolveConfig>[0] extends undefined ? never : NonNullable<Parameters<typeof resolveConfig>[0]>['weights'],
        passingThreshold: rawScoringConfig.passingThreshold as number | undefined,
        excludeModules: rawScoringConfig.excludeModules as string[] | undefined,
      }
    : {};

  const result = await engine.score({
    designSystem: {
      id: config.designSystemId,
      name: dsName,
      typography: typographyConfig,
    },
    scoringConfig,
    changedFiles: changedFiles.length > 0 ? changedFiles : undefined,
    triggeredBy: 'ci',
  });

  core.info(`Health score: ${result.score.overall}/100 (${scoreToGrade(result.score.overall)})`);

  // 4. Fetch previous snapshot for regression detection
  let previousScore: number | null = null;
  try {
    const { data: baseline } = await supabase.rpc('get_health_baseline', {
      p_design_system_id: config.designSystemId,
    });
    const rows = baseline as Array<{ overall_score: number }> | null;
    const first = rows?.[0];
    if (first) {
      previousScore = first.overall_score;
    }
  } catch {
    core.debug('No previous snapshot found for regression comparison');
  }

  const delta = previousScore !== null ? result.score.overall - previousScore : null;

  // 5. Evaluate thresholds
  const passesThreshold = config.scoreThreshold <= 0 || result.score.overall >= config.scoreThreshold;
  const passesRegression =
    config.regressionThreshold <= 0 ||
    delta === null ||
    delta >= -config.regressionThreshold;

  if (!passesThreshold) {
    core.warning(`Health score ${result.score.overall} is below threshold ${config.scoreThreshold}`);
  }
  if (!passesRegression) {
    core.warning(`Health score dropped by ${Math.abs(delta!)} points (threshold: ${config.regressionThreshold})`);
  }

  // 6. Save snapshot to DB
  try {
    const { error: snapError } = await supabase
      .from('health_snapshots')
      .insert({
        design_system_id: config.designSystemId,
        layer_id: config.layerId ?? null,
        overall_score: result.score.overall,
        scores: {
          tokenAdoption: result.score.tokenAdoption,
          presetAdoption: result.score.presetAdoption,
          accessibility: result.score.accessibility,
          consistency: result.score.consistency,
        },
        violation_summary: result.violationSummary,
        files_scanned: result.filesScanned,
        triggered_by: 'ci',
      });

    if (snapError) {
      core.debug(`Failed to save snapshot: ${snapError.message}`);
    } else {
      core.info('Saved health snapshot');
    }
  } catch {
    core.debug('Failed to save health snapshot');
  }

  return {
    overall: result.score.overall,
    dimensions: {
      tokenAdoption: result.score.tokenAdoption,
      presetAdoption: result.score.presetAdoption,
      accessibility: result.score.accessibility,
      consistency: result.score.consistency,
    },
    previousScore,
    delta,
    passesThreshold,
    passesRegression,
    grade: scoreToGrade(result.score.overall),
  };
}

// =============================================================================
// Token → TypographyConfig (simplified for CI context)
// =============================================================================

interface TokenRow {
  name: string;
  category: string;
  /**
   * The raw JSONB cell. `unknown` on purpose — declaring it `{light, dark}` is what made
   * this scorer read `value.light` and score every non-theme-keyed system's typography as
   * absent, silently (PRE-2438). Read it with `readTokenValue`, never by indexing.
   */
  value: unknown;
  metadata: Record<string, unknown> | null;
}

function tokensToTypographyConfig(tokens: TokenRow[]): Record<string, unknown> {
  const fontSize: Record<string, string> = {};
  const fontFamily: Record<string, string> = {};
  const fontWeight: Record<string, number> = {};
  const lineHeight: Record<string, string> = {};

  for (const token of tokens) {
    const value = readTokenValue(token.value).value;
    if (!value) continue;

    const cat = token.category?.toLowerCase() ?? '';
    const key = token.name.split(/[-./]/).pop() ?? token.name;

    if (cat.includes('size') || cat.includes('font-size')) {
      fontSize[key] = value;
    } else if (cat.includes('family') || cat.includes('font-family')) {
      fontFamily[key] = value;
    } else if (cat.includes('weight') || cat.includes('font-weight')) {
      const num = parseInt(value, 10);
      if (!isNaN(num)) fontWeight[key] = num;
    } else if (cat.includes('line-height') || cat.includes('leading')) {
      lineHeight[key] = value;
    }
  }

  const config: Record<string, unknown> = {};
  if (Object.keys(fontSize).length > 0) config.fontSize = fontSize;
  if (Object.keys(fontFamily).length > 0) config.fontFamily = fontFamily;
  if (Object.keys(fontWeight).length > 0) config.fontWeight = fontWeight;
  if (Object.keys(lineHeight).length > 0) config.lineHeight = lineHeight;
  return config;
}

// =============================================================================
// Baseline Comparison (PRE-615)
// =============================================================================

/**
 * Compare current violations against the baseline snapshot.
 * Returns new vs legacy violation counts using get_violation_diff RPC.
 */
export async function getBaselineCompare(
  config: ActionConfig,
  currentSnapshotId: string,
): Promise<BaselineCompare | null> {
  if (!config.failOnNewOnly) return null;
  if (!config.supabaseUrl || !config.supabaseKey || !config.designSystemId) return null;

  const supabase = createSupabaseClient(config.supabaseUrl, config.supabaseKey);

  // Get baseline snapshot ID (column may not be in generated types)
  const { data: ds } = await supabase
    .from('design_systems')
    .select('baseline_snapshot_id')
    .eq('id', config.designSystemId)
    .single() as { data: { baseline_snapshot_id: string | null } | null; error: unknown };

  const baselineId = ds?.baseline_snapshot_id;
  if (!baselineId) {
    core.info('No baseline set — fail-on-new-only has no effect without a baseline');
    return null;
  }

  // Run violation diff (RPC may not be in generated types)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const { data: diffRows, error } = await (supabase as any).rpc('get_violation_diff', {
    p_baseline_snapshot_id: baselineId,
    p_current_snapshot_id: currentSnapshotId,
  }) as { data: Array<{ is_new: boolean }> | null; error: { message: string } | null };

  if (error) {
    core.warning(`Baseline diff failed: ${error.message}`);
    return null;
  }

  const rows = (diffRows || []) as Array<{ is_new: boolean }>;
  const newCount = rows.filter(r => r.is_new).length;
  const legacyCount = rows.filter(r => !r.is_new).length;

  core.info(`Baseline compare: ${newCount} new, ${legacyCount} legacy violations`);

  return {
    newViolationCount: newCount,
    legacyViolationCount: legacyCount,
    baselineSnapshotId: baselineId,
  };
}
