/**
 * Gateway full mode client (PRE-2873 step 2): validate changed files through
 * the hosted MCP gateway's `validate_code`, authenticated with GitHub Actions
 * OIDC (or `preset-api-key`), instead of reading the design system with an
 * anonymous Supabase key that a private design system answers with zero rows.
 *
 * Design: docs/architecture/github-action-gateway-validation.md. The transport
 * pattern follows scripts/museum-doctrine-gate.mjs (fresh transport per
 * attempt, PRE-2435; bearer re-minted near expiry), with one difference by
 * contract: the gate degrades on exhausted monthly allowance and this does not.
 *
 * Every failure is thrown as a `GatewayFailure`, which callers turn into a
 * failed result. Nothing here ever falls back to basic mode.
 *
 * All side effects (fetch, OIDC mint, sleep) are injected so the real MCP SDK
 * can be exercised against a fake gateway in tests.
 */

// CJS subpaths on purpose: ncc bundles this Action as CommonJS, and the SDK's
// `require` condition resolves to its dist/cjs build (PRE-1658 was an ESM build
// embedded into CJS crashing at load).
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';

import type { ActionConfig } from './types.js';
import { ACTION_VERSION } from './version.js';
import {
  classifyHttpFailure,
  createWaitBudget,
  mcpEndpoint,
  parseBoundTenant,
  parseRetryAfter,
  parseValidateResult,
  tenantMismatch,
  type HttpFailure,
  type ParsedValidateResult,
} from './gateway-mode.js';

export class GatewayFailure extends Error {
  constructor(
    message: string,
    /** True when the failure is a design system mismatch (the callback is skipped). */
    readonly tenantMismatch = false,
  ) {
    super(message);
    this.name = 'GatewayFailure';
  }
}

export type CredentialSource = 'oidc' | 'api-key';

export interface GatewayDeps {
  fetch: typeof fetch;
  /** Mint a GitHub Actions OIDC token for an audience (core.getIDToken in production). */
  mintIdToken: (audience: string) => Promise<string>;
  /** Whether the runner can mint an OIDC token (the job has id-token: write). */
  oidcAvailable: () => boolean;
  sleep: (ms: number) => Promise<void>;
  log: (msg: string) => void;
}

export interface GatewayConnection {
  boundDesignSystemId: string;
  boundLabel: string | null;
  credentialSource: CredentialSource;
  validate(input: { code: string; filePath: string; layerId?: string }): Promise<ParsedValidateResult>;
  close(): Promise<void>;
}

const REQUIRED_TOOL = 'validate_code';
const REFRESH_MARGIN_S = 60;
const NETWORK_RETRIES = 3;
const NETWORK_RETRY_WAIT_S = 2;
const MAX_RECORDED_BODY = 4000;

function jwtExp(jwt: string): number | null {
  const payload = jwt.split('.')[1];
  if (!payload) return null;
  try {
    const exp = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')).exp;
    return Number.isFinite(exp) ? exp : null;
  } catch {
    return null;
  }
}

/**
 * PRE-3040: whether this run has ANY credential it could try (OIDC capable, or
 * a `preset-api-key` configured), without actually attempting the mint. A
 * pure yes/no used by `index.ts` to decide the fork/Dependabot generic-only
 * carve-out before it ever opens a gateway connection. `resolveCredential`
 * below calls this too, so the two call sites can never disagree about what
 * "has a credential" means.
 */
export function credentialAvailable(
  config: Pick<ActionConfig, 'presetApiKey'>,
  oidcAvailable: () => boolean,
): boolean {
  return oidcAvailable() || Boolean(config.presetApiKey);
}

/**
 * Resolve the bearer source. OIDC when the runner can mint it; a refused mint
 * falls back to `preset-api-key` when one is configured (both reach the same
 * gateway, so neither is a weaker check). Neither: GatewayFailure.
 */
async function resolveCredential(
  config: Pick<ActionConfig, 'presetApiKey' | 'mcpOidcAudience'>,
  deps: GatewayDeps,
): Promise<{ source: CredentialSource; token: () => Promise<string> }> {
  // PRE-3040: fail fast, before attempting anything, when there is nothing to
  // try at all. Behavior-preserving: when oidcAvailable() is true this is
  // always true too, so the mint attempt below still runs exactly as before;
  // it only short-circuits the case that used to fall through both branches
  // to the same "needs a credential" throw at the bottom.
  if (!credentialAvailable(config, deps.oidcAvailable)) {
    throw new GatewayFailure(
      'Full mode needs a credential for the preset AI gateway: grant the job `permissions: id-token: write` ' +
        '(with the preset AI GitHub App installed), or set preset-api-key.',
    );
  }
  let mintError: string | null = null;
  if (deps.oidcAvailable()) {
    let current: string | null = null;
    let exp: number | null = null;
    const mint = async () => {
      const t = await deps.mintIdToken(config.mcpOidcAudience);
      if (!t) throw new Error('OIDC mint returned an empty token');
      current = t;
      exp = jwtExp(t);
      return t;
    };
    try {
      await mint();
      return {
        source: 'oidc',
        token: async () => {
          // An unreadable exp is treated as expiring: re-mint rather than reuse
          // a token whose lifetime is unknown.
          if (current === null || exp === null || exp - Date.now() / 1000 < REFRESH_MARGIN_S) return mint();
          return current;
        },
      };
    } catch (err) {
      mintError = err instanceof Error ? err.message : String(err);
    }
  }
  if (config.presetApiKey) {
    if (mintError) deps.log(`GitHub OIDC token mint failed (${mintError}); using preset-api-key.`);
    const key = config.presetApiKey;
    return { source: 'api-key', token: async () => key };
  }
  throw new GatewayFailure(
    mintError
      ? `Full mode could not authenticate to the preset AI gateway: the GitHub OIDC token mint failed (${mintError}) and preset-api-key is not set.`
      : 'Full mode needs a credential for the preset AI gateway: grant the job `permissions: id-token: write` ' +
          '(with the preset AI GitHub App installed), or set preset-api-key.',
  );
}

/**
 * Open the gateway connection: credential, initialize (with retry), the bound
 * design system check, and the `validate_code` capability preflight. On any
 * failure every client opened along the way is closed before the throw.
 */
export async function connectGateway(
  config: Pick<ActionConfig, 'presetApiKey' | 'mcpOidcAudience' | 'mcpGatewayUrl' | 'designSystemId'>,
  deps: GatewayDeps,
): Promise<GatewayConnection> {
  const credential = await resolveCredential(config, deps);
  let endpoint: URL;
  try {
    endpoint = new URL(mcpEndpoint(config.mcpGatewayUrl));
  } catch {
    // A configuration error, reported on the same fail-closed result path as
    // any other gateway failure (Codex, #2643 round 1).
    throw new GatewayFailure(
      `mcp-gateway-url is not a valid URL (${JSON.stringify(config.mcpGatewayUrl)}). Use a full URL such as https://mcp.presetai.dev.`,
    );
  }
  const budget = createWaitBudget();

  // The SDK's StreamableHTTPError keeps only the status and drops Retry-After,
  // so the fetch wrapper records every non-2xx response and the retry policy
  // reads that record, not the thrown error.
  let lastFailure: HttpFailure | null = null;
  const recordingFetch: typeof fetch = async (input, init = {}) => {
    const headers = new Headers(init.headers);
    headers.set('Authorization', `Bearer ${await credential.token()}`);
    const res = await deps.fetch(input, { ...init, headers });
    const method = (init.method ?? 'GET').toUpperCase();
    // The standalone SSE GET may be refused (405) by design; only POSTs carry
    // the calls whose failures matter.
    if (!res.ok && method === 'POST') {
      let body = '';
      try {
        body = (await res.clone().text()).slice(0, MAX_RECORDED_BODY);
      } catch {
        // Unreadable body: classify on status alone.
      }
      lastFailure = { status: res.status, retryAfterSeconds: parseRetryAfter(res.headers.get('retry-after')), body };
    }
    return res;
  };

  /**
   * Run `op` with the rate-limit and network retry policy. `op` must be safe
   * to repeat: initialize, tools/list and validate_code all are.
   */
  async function withRetry<T>(
    label: string,
    op: () => Promise<T>,
    onFailedAttempt?: () => Promise<void>,
    // Network errors leave it unknown whether the server ran the request. Only
    // operations that are harmless to repeat may retry them; validate_code is
    // not (it draws on the allowance and can write traces and drift catches),
    // so it retries only a recorded rate-limit refusal, which the gateway
    // returns before running the tool (Codex, #2643 round 2).
    retryNetwork = true,
  ): Promise<T> {
    let networkAttempts = 0;
    for (;;) {
      lastFailure = null;
      try {
        return await op();
      } catch (err) {
        if (onFailedAttempt) await onFailedAttempt();
        if (err instanceof GatewayFailure) throw err;
        const failure = lastFailure as HttpFailure | null;
        const message = err instanceof Error ? err.message : String(err);
        if (failure) {
          const c = classifyHttpFailure(failure);
          if (c.kind === 'terminal') throw new GatewayFailure(`${label}: ${c.message}`);
          const wait = budget.take(c.waitSeconds);
          if (wait === null) {
            throw new GatewayFailure(
              `${label}: still rate limited after waiting ${budget.spent}s in total, the most this Action waits per run.`,
            );
          }
          deps.log(`${label}: ${c.detail}; retrying in ${wait}s.`);
          await deps.sleep(wait * 1000);
          continue;
        }
        // No HTTP response recorded: a network-level failure, or a JSON-RPC
        // error inside a 2xx body (not retryable).
        if (
          retryNetwork &&
          /fetch failed|ECONN|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket|network/i.test(message) &&
          networkAttempts < NETWORK_RETRIES
        ) {
          networkAttempts++;
          const wait = budget.take(NETWORK_RETRY_WAIT_S);
          if (wait !== null) {
            deps.log(`${label}: ${message}; retrying in ${wait}s.`);
            await deps.sleep(wait * 1000);
            continue;
          }
        }
        throw new GatewayFailure(`${label}: ${message}`);
      }
    }
  }

  // A fresh transport AND client per attempt (PRE-2435): a transport is
  // single-use, and reusing one masks the real failure with "Already connected".
  let client: Client | null = null;
  const closeQuietly = async (c: Client | null) => {
    if (!c) return;
    try {
      await c.close();
    } catch {
      // Closing a half-open client can throw; nothing to do.
    }
  };
  let attempt: Client | null = null;
  await withRetry(
    `Could not connect to the preset AI gateway (${endpoint.href})`,
    async () => {
      attempt = new Client({ name: 'preset-compliance-check', version: ACTION_VERSION });
      const transport = new StreamableHTTPClientTransport(endpoint, { fetch: recordingFetch });
      await attempt.connect(transport);
      client = attempt;
    },
    async () => {
      await closeQuietly(attempt);
      attempt = null;
    },
  );
  const connected = client as unknown as Client;

  try {
    const bound = parseBoundTenant(connected.getInstructions());
    const mismatch = tenantMismatch(config.designSystemId!, bound);
    if (mismatch) throw new GatewayFailure(mismatch, true);

    const listed = await withRetry('tools/list', () => connected.listTools());
    const names = new Set((listed?.tools ?? []).map((t) => t.name));
    if (!names.has(REQUIRED_TOOL)) {
      throw new GatewayFailure(
        `This credential can connect but cannot run ${REQUIRED_TOOL} (${names.size} tools available). ` +
          'Validation needs author scope: for OIDC, the preset AI GitHub App installation must have author scope; ' +
          'for preset-api-key, use a Standard key.',
      );
    }

    return {
      boundDesignSystemId: bound.id!,
      boundLabel: bound.label,
      credentialSource: credential.source,
      async validate({ code, filePath, layerId }) {
        const result = await withRetry(
          `validate_code ${filePath}`,
          () =>
            connected.callTool({
              name: REQUIRED_TOOL,
              arguments: { code, filePath, includeDefaults: false, ...(layerId ? { layerId } : {}) },
            }),
          undefined,
          false,
        );
        try {
          return parseValidateResult(result);
        } catch (err) {
          throw new GatewayFailure(`validate_code ${filePath}: ${err instanceof Error ? err.message : String(err)}`);
        }
      },
      close: () => closeQuietly(connected),
    };
  } catch (err) {
    await closeQuietly(connected);
    throw err;
  }
}
