/**
 * Auto-apply design-system codemods and commit them back to the PR (PRE-1933).
 *
 * Opt-in via the `apply-fixes` input. For each changed JSX/TSX file we run the
 * @preset/core codemod with the DEFAULT contract (non-breaking, high-confidence
 * transforms only — `applyBreaking` stays false), then commit the rewritten
 * files back to the PR head branch in a single commit via the GitHub git data
 * API (blobs → tree → commit → update-ref).
 *
 * READS AND WRITES THE PR HEAD — NOT the local checkout. On `pull_request`
 * events `actions/checkout` commonly checks out GitHub's synthetic *merge ref*
 * (head merged into base), so the on-disk `file.content` (used by validation)
 * is the merged content, not the head content. Committing those blobs back onto
 * the head branch would silently copy base-branch / merge-resolution output into
 * the contributor's branch. So the mutating path is self-consistent: resolve the
 * current head sha ONCE, fetch each file's content AT THAT SHA, run the codemod
 * on it, and commit on top of it. (PRE-1933 review — Codex P1.)
 *
 * Truthful telemetry: `fixesApplied` counts only transforms we actually
 * COMMITTED. If the commit can't happen — fork PR (token can't push to the fork
 * branch), missing `contents: write`, or any API error — we return 0 so the
 * downstream validate_fix emit (gateway, PRE-1933) never fires for a fix the
 * customer didn't receive. The commit IS the accept.
 */

import * as core from '@actions/core';
import * as github from '@actions/github';
import { applyCodemod } from '@preset/core/codemod';
import type { ActionConfig, ChangedFile } from './types.js';

// The codemod parses with recast's babel-ts parser; only JSX/TSX is in scope.
const JSX_FILE_RE = /\.(?:tsx|jsx)$/i;

type Octokit = ReturnType<typeof github.getOctokit>;

export interface ApplyFixesResult {
  /** Transforms actually committed back to the PR branch (0 if not committed). */
  fixesApplied: number;
  /** Distinct rule ids that produced the committed transforms. */
  rulesApplied: string[];
  /** Files rewritten + committed. */
  filesFixed: number;
  /** Whether the autofix commit landed on the PR branch. */
  committed: boolean;
}

const EMPTY: ApplyFixesResult = { fixesApplied: 0, rulesApplied: [], filesFixed: 0, committed: false };

interface FixedFile {
  path: string;
  content: string;
}

export async function applyFixes(files: ChangedFile[], config: ActionConfig): Promise<ApplyFixesResult> {
  const { context } = github;
  // pull_request payload is loosely typed; narrow the bits we need.
  const pr = context.payload.pull_request as
    | { head?: { ref?: string; repo?: { full_name?: string } } }
    | undefined;
  if (!pr) {
    core.info('[apply-fixes] no pull_request context; skipping autofix.');
    return EMPTY;
  }

  // Fork PRs: the default GITHUB_TOKEN is read-only on the fork's branch, so we
  // can't push the fix. Skip rather than claim an uncommitted fix.
  const headRepo = pr.head?.repo?.full_name;
  const baseRepo = `${context.repo.owner}/${context.repo.repo}`;
  if (headRepo && headRepo !== baseRepo) {
    core.warning(
      `[apply-fixes] PR head is a fork (${headRepo}); cannot push autofixes to a fork branch. Skipping.`,
    );
    return EMPTY;
  }
  const branch = pr.head?.ref;
  if (!branch) {
    core.warning('[apply-fixes] could not resolve PR head branch; skipping autofix.');
    return EMPTY;
  }

  // Paths only — content is re-read from the PR head below, never from the
  // (possibly-merged) local checkout.
  const candidatePaths = files.filter((f) => JSX_FILE_RE.test(f.path)).map((f) => f.path);
  if (candidatePaths.length === 0) {
    core.info('[apply-fixes] no changed JSX/TSX files in scope.');
    return EMPTY;
  }

  const octokit = github.getOctokit(config.githubToken);
  const owner = context.repo.owner;
  const repo = context.repo.repo;

  // Resolve the CURRENT head once. Both the content reads and the commit are
  // anchored to this sha, so read and write can't straddle different trees.
  let headSha: string;
  let baseTreeSha: string;
  try {
    const { data: ref } = await octokit.rest.git.getRef({ owner, repo, ref: `heads/${branch}` });
    headSha = ref.object.sha;
    const { data: headCommit } = await octokit.rest.git.getCommit({ owner, repo, commit_sha: headSha });
    baseTreeSha = headCommit.tree.sha;
  } catch (e) {
    core.warning(`[apply-fixes] could not resolve PR head ${branch}: ${msg(e)}`);
    return EMPTY;
  }

  // Run the codemod (non-breaking, high-confidence only) over the HEAD content.
  const fixed: FixedFile[] = [];
  const rules = new Set<string>();
  let fixesApplied = 0;
  for (const path of candidatePaths) {
    let headContent: string | null;
    try {
      headContent = await readFileAtRef(octokit, owner, repo, path, headSha);
    } catch (e) {
      core.warning(`[apply-fixes] could not read ${path} at PR head: ${msg(e)}`);
      continue;
    }
    if (headContent === null) continue; // not a regular file at head, or absent

    let res;
    try {
      res = applyCodemod(headContent, { fileName: path });
    } catch (e) {
      core.warning(`[apply-fixes] codemod failed on ${path}: ${msg(e)}`);
      continue;
    }
    if (!res.changed || res.applied.length === 0) continue;
    fixed.push({ path, content: res.fixed });
    for (const c of res.applied) rules.add(c.rule);
    fixesApplied += res.applied.length;
  }

  if (fixed.length === 0) {
    core.info('[apply-fixes] no auto-applicable (non-breaking) fixes found.');
    return EMPTY;
  }

  const committed = await commitFixes(octokit, owner, repo, branch, headSha, baseTreeSha, fixed);
  if (!committed) {
    // Commit failed — do NOT report fixes (keeps the validate_fix emit truthful).
    return EMPTY;
  }

  const ruleList = [...rules];
  core.info(
    `[apply-fixes] committed ${fixesApplied} fix(es) across ${fixed.length} file(s) on ${branch}: ${ruleList.join(', ')}`,
  );
  return { fixesApplied, rulesApplied: ruleList, filesFixed: fixed.length, committed: true };
}

/**
 * Read a file's content at a specific ref (the PR head sha). Returns null when
 * the path is not a regular file at that ref. Uses the contents API, falling
 * back to the blob API for files the contents API returns empty (> 1 MB).
 */
async function readFileAtRef(
  octokit: Octokit,
  owner: string,
  repo: string,
  path: string,
  ref: string,
): Promise<string | null> {
  const { data } = await octokit.rest.repos.getContent({ owner, repo, path, ref });
  if (Array.isArray(data)) return null; // a directory listing
  const file = data as { type?: string; content?: string; encoding?: string; sha?: string };
  if (file.type !== 'file') return null; // submodule / symlink

  if (typeof file.content === 'string' && file.content.length > 0 && file.encoding === 'base64') {
    return Buffer.from(file.content, 'base64').toString('utf-8');
  }
  // Large file: contents API inlines nothing; fetch the blob by sha.
  if (!file.sha) return null;
  const { data: blob } = await octokit.rest.git.getBlob({ owner, repo, file_sha: file.sha });
  const encoding: BufferEncoding = blob.encoding === 'base64' ? 'base64' : 'utf-8';
  return Buffer.from(blob.content, encoding).toString('utf-8');
}

/**
 * Commit the rewritten files to the PR head branch in one commit via the git
 * data API, on top of `headSha` (the same sha the content was read from).
 * Returns false (with a warning) on any failure — most commonly a missing
 * `contents: write` permission.
 */
async function commitFixes(
  octokit: Octokit,
  owner: string,
  repo: string,
  branch: string,
  headSha: string,
  baseTreeSha: string,
  fixed: FixedFile[],
): Promise<boolean> {
  try {
    const tree: { path: string; mode: '100644'; type: 'blob'; sha: string }[] = [];
    for (const f of fixed) {
      const { data: blob } = await octokit.rest.git.createBlob({
        owner,
        repo,
        content: Buffer.from(f.content, 'utf-8').toString('base64'),
        encoding: 'base64',
      });
      tree.push({ path: f.path, mode: '100644', type: 'blob', sha: blob.sha });
    }

    const { data: newTree } = await octokit.rest.git.createTree({ owner, repo, base_tree: baseTreeSha, tree });

    const fileWord = fixed.length === 1 ? 'file' : 'files';
    const { data: commit } = await octokit.rest.git.createCommit({
      owner,
      repo,
      message:
        `style: apply preset design-system autofixes (${fixed.length} ${fileWord})\n\n` +
        'Non-breaking, high-confidence codemods applied by the Preset Design System ' +
        'Check action (apply-fixes). Re-run validate to confirm.',
      tree: newTree.sha,
      parents: [headSha],
    });

    // force:false — never clobber a concurrent push. If the branch advanced
    // since we read headSha, this fails; we warn and the next run re-applies
    // (the codemod is idempotent), reading the new head.
    await octokit.rest.git.updateRef({ owner, repo, ref: `heads/${branch}`, sha: commit.sha, force: false });
    return true;
  } catch (e) {
    core.warning(
      `[apply-fixes] could not commit autofixes to ${branch} ` +
        `(grant the workflow \`permissions: contents: write\`, or the branch advanced mid-run): ${msg(e)}`,
    );
    return false;
  }
}

function msg(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}
