/**
 * Retrieves files changed in a PR and reads their contents (PRE-329).
 */

import * as core from '@actions/core';
import * as github from '@actions/github';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { minimatch } from 'minimatch';
import type { ActionConfig, ChangedFile } from './types.js';

/** File extensions relevant to design system validation. */
const RELEVANT_EXTENSIONS = new Set(['.tsx', '.jsx', '.ts', '.vue', '.svelte', '.css']);

export async function getChangedFiles(config: ActionConfig): Promise<ChangedFile[]> {
  const { context } = github;
  const prNumber = context.payload.pull_request?.number;

  if (!prNumber) {
    core.warning('No pull request context found. Skipping changed-file detection.');
    return [];
  }

  const octokit = github.getOctokit(config.githubToken);

  // Paginate through all changed files
  const files: { filename: string; status: string }[] = [];
  let page = 1;
  // eslint-disable-next-line no-constant-condition
  while (true) {
    const { data } = await octokit.rest.pulls.listFiles({
      owner: context.repo.owner,
      repo: context.repo.repo,
      pull_number: prNumber,
      per_page: 100,
      page,
    });
    if (data.length === 0) break;
    files.push(...data.map(f => ({ filename: f.filename, status: f.status })));
    if (data.length < 100) break;
    page++;
  }

  const changedFiles: ChangedFile[] = [];

  for (const file of files) {
    // Skip deleted files
    if (file.status === 'removed') continue;

    // Check extension
    const ext = path.extname(file.filename);
    if (!RELEVANT_EXTENSIONS.has(ext)) continue;

    // Check include/exclude globs
    const included = config.include.some(glob => minimatch(file.filename, glob));
    if (!included) continue;

    const excluded = config.exclude.some(glob => minimatch(file.filename, glob));
    if (excluded) continue;

    // Read file content (already checked out by actions/checkout)
    const filePath = path.resolve(process.cwd(), file.filename);
    if (!fs.existsSync(filePath)) {
      core.debug(`File not found on disk: ${file.filename}`);
      continue;
    }

    try {
      const content = fs.readFileSync(filePath, 'utf-8');
      changedFiles.push({ path: file.filename, content });
    } catch (e) {
      core.warning(`Could not read ${file.filename}: ${e}`);
    }
  }

  core.info(`Found ${changedFiles.length} design-system-relevant files in PR #${prNumber}`);
  return changedFiles;
}
