/**
 * The full-mode-with-zero-binding-rules fail gate (PRE-2873).
 *
 * Split out as a pure function for the same reason severity.ts and
 * comment-markdown.ts are separate modules: index.ts imports `@actions/core`
 * and runs the Action as a side effect of being imported, which makes it
 * untestable under the tsx test runner. This module has no such import, so
 * the gate's decision logic can be unit tested directly.
 *
 * Background (PRE-2873): `uncheckedFiles` (PRE-2897) counts changed files
 * against which zero of the design system's binding rules applied. In basic
 * mode (no Supabase credentials) that count is ALWAYS > 0 for every file,
 * by construction (no `dbValidator` ever runs, so no file is ever checked
 * against a design system). Gating on `isFullModeEnabled` is what keeps a
 * basic-mode user, who never configured full mode, from failing on this: the
 * gate only fires for a user who configured full mode and whose rules still
 * did not apply to the diff.
 */

import type { ActionConfig, ActionResult } from './types.js';
import { isFullModeEnabled } from './types.js';
import { resolveValidationMode } from './gateway-mode.js';

export interface UncheckedGateResult {
  /** Whether this run should fail because of unchecked files. */
  shouldFail: boolean;
  /** Full explanation for the Action log. Null when shouldFail is false. */
  warningMessage: string | null;
  /** Short phrase for the `failReasons` list. Null when shouldFail is false. */
  failReason: string | null;
}

/**
 * Decide whether a run should fail because full mode was configured but none
 * of the design system's binding rules applied to one or more changed files.
 *
 * Fails when ALL of:
 * - full mode is enabled (design-system-id set, by either backend; see resolveValidationMode)
 * - the gateway did not fail the run (that is reported as its own reason)
 * - at least one changed file had zero binding rules applied (`uncheckedFiles > 0`)
 * - the run did not opt out (`allow-unchecked: true`)
 */
export function evaluateUncheckedGate(
  config: ActionConfig,
  result: ActionResult,
): UncheckedGateResult {
  // PRE-2873 step 2: when the gateway could not check the run, that failure is
  // the reason and is reported on its own; counting the files it never reached
  // as "no binding rules" would misstate the cause.
  // PRE-3040: a fork/Dependabot PR with no credential ran generic checks
  // only. `index.ts` calls this with the ORIGINAL config (designSystemId
  // still set), so `isFullModeEnabled(config)` alone would not bypass it;
  // this field is the bypass.
  if (
    !isFullModeEnabled(config) ||
    result.uncheckedFiles <= 0 ||
    config.allowUnchecked ||
    result.gatewayFailure ||
    result.forkGenericOnly
  ) {
    return { shouldFail: false, warningMessage: null, failReason: null };
  }

  const plural = result.filesChecked !== 1 ? 's' : '';
  const mode = resolveValidationMode(config);
  const legacy = mode.ok && mode.mode === 'legacy';

  return {
    shouldFail: true,
    warningMessage:
      `Full mode is configured, but ${result.uncheckedFiles} of ${result.filesChecked} changed ` +
      `file${plural} had no binding rules from your design system applied. This usually means ` +
      `${legacy ? 'the supabase-key cannot read this design system (a private design system returns zero rows to an anonymous key; remove supabase-url and supabase-key to validate through the preset AI gateway) or ' : ''}` +
      `design-system-id points to a design system with no rules at warn or block for these files. ` +
      `If this run is expected to have no design-system coverage, set allow-unchecked: true.`,
    failReason:
      `${result.uncheckedFiles} of ${result.filesChecked} file${plural} had no binding design ` +
      `system rules applied (check ${legacy ? 'supabase-key and ' : ''}design-system-id, or set allow-unchecked: true)`,
  };
}
