/**
 * SARIF output for GitHub Code Scanning (PRE-329, enhanced PRE-618).
 *
 * Uses the shared @preset/health SARIF generator for health violations,
 * and converts action-specific file violations to the unified format.
 */

import * as fs from 'node:fs';
import * as path from 'node:path';
import { toSarif } from '@preset/health';
import type { Violation } from '@preset/health';
import type { ActionResult } from './types.js';
import { sarifSeverity } from './severity.js';

/**
 * Generate SARIF log from action results.
 * Merges file violations (from validation) with health violations (from scoring).
 */
export function generateSarif(result: ActionResult) {
  // Convert file violations to unified Violation format
  const violations: Violation[] = [];

  for (const fv of result.fileViolations) {
    for (const v of fv.violations) {
      violations.push({
        rule: v.ruleId,
        file: fv.path,
        line: v.line ?? 1,
        column: 0,
        message: v.fix || v.ruleId,
        severity: sarifSeverity(v.severity),
        fix: v.fix,
      });
    }
  }

  return toSarif(violations, {
    toolName: '@preset/github-action',
    toolVersion: '0.1.0',
    toolUri: 'https://www.presetai.dev',
    includeSnippets: true,
    includeFixes: true,
  });
}

export function writeSarif(result: ActionResult): string {
  const sarif = generateSarif(result);
  const outputDir = path.resolve(process.cwd(), '.preset-results');
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }
  const outputPath = path.join(outputDir, 'results.sarif');
  fs.writeFileSync(outputPath, JSON.stringify(sarif, null, 2));
  return outputPath;
}
