// src/schema/pattern-compiler.ts
function severityForRuleType(type, ruleSeverity) {
  if (ruleSeverity === "error" || ruleSeverity === "warning" || ruleSeverity === "info") {
    return ruleSeverity;
  }
  switch (type) {
    case "must":
    case "must_not":
      return "error";
    case "should":
    case "should_not":
      return "warning";
    default:
      return "warning";
  }
}
function dimensionForCategory(category) {
  switch (category) {
    case "form":
    case "interaction":
      return "presetAdoption";
    case "layout":
    case "navigation":
    case "data-display":
      return "consistency";
    case "feedback":
    case "overlay":
      return "accessibility";
    case "content":
    default:
      return "tokenAdoption";
  }
}
function extractPattern(rule, type) {
  if (rule.selector) {
    try {
      return new RegExp(rule.selector);
    } catch {
      return new RegExp(escapeRegex(rule.selector));
    }
  }
  if (rule.validation) {
    try {
      return new RegExp(rule.validation);
    } catch {
      return null;
    }
  }
  if (rule.examples) {
    const example = type === "must_not" || type === "should_not" ? rule.examples.bad : rule.examples.good;
    if (example) {
      const pattern = extractCodePattern(example);
      if (pattern) return pattern;
    }
  }
  return extractFromDescription(rule.description);
}
function extractCodePattern(code) {
  const trimmed = code.trim();
  const jsxMatch = trimmed.match(/^<(\w+)/);
  if (jsxMatch?.[1]) {
    return new RegExp(`<${escapeRegex(jsxMatch[1])}[\\s/>]`);
  }
  const classMatch = trimmed.match(/className\s*=\s*["']([^"']+)["']/);
  if (classMatch?.[1]) {
    const classes = classMatch[1].split(/\s+/).filter((c) => c.length > 2);
    if (classes.length > 0) {
      return new RegExp(classes.map((c) => escapeRegex(c)).join("|"));
    }
  }
  const cssMatch = trimmed.match(/^([\w-]+)\s*:\s*(.+)/);
  if (cssMatch?.[1] && cssMatch[2]) {
    return new RegExp(`${escapeRegex(cssMatch[1])}\\s*:\\s*${escapeRegex(cssMatch[2].trim())}`);
  }
  const fnMatch = trimmed.match(/^(\w+)\s*\(/);
  if (fnMatch?.[1]) {
    return new RegExp(`${escapeRegex(fnMatch[1])}\\s*\\(`);
  }
  return null;
}
function extractFromDescription(description) {
  const quotedMatches = description.match(/["'`]([^"'`]+)["'`]/g);
  if (quotedMatches && quotedMatches.length > 0) {
    const terms = quotedMatches.map((m) => m.slice(1, -1)).filter((t) => t.length >= 2 && !/^[A-Z]/.test(t));
    if (terms.length > 0) {
      return new RegExp(terms.map((t) => escapeRegex(t)).join("|"));
    }
  }
  const codeMatches = description.match(/`([^`]+)`/g);
  if (codeMatches && codeMatches.length > 0) {
    const terms = codeMatches.map((m) => m.slice(1, -1)).filter((t) => t.length >= 2);
    if (terms.length > 0) {
      return new RegExp(terms.map((t) => escapeRegex(t)).join("|"));
    }
  }
  const tagMatches = description.match(/<(\w+)>/g);
  if (tagMatches && tagMatches.length > 0) {
    const tags = tagMatches.map((m) => m.slice(1, -1));
    return new RegExp(tags.map((t) => `<${escapeRegex(t)}[\\s/>]`).join("|"));
  }
  return null;
}
function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}
function compilePattern(pattern) {
  const rules = [];
  const skipped = [];
  const dimension = dimensionForCategory(pattern.category);
  for (let i = 0; i < pattern.rules.length; i++) {
    const rule = pattern.rules[i];
    if (!rule) continue;
    const regex = extractPattern(rule, rule.type);
    if (!regex) {
      skipped.push({
        rule,
        reason: "Could not extract executable pattern from selector, validation, examples, or description"
      });
      continue;
    }
    const isNegative = rule.type === "must_not" || rule.type === "should_not";
    const severity = severityForRuleType(rule.type, rule.severity);
    const messagePrefix = isNegative ? "Forbidden" : "Required";
    rules.push({
      id: `${pattern.name}.rule-${i}`,
      description: rule.description,
      pattern: regex,
      severity,
      dimension,
      message: `${messagePrefix}: ${rule.description}`,
      fix: rule.rationale ?? void 0,
      sourcePatternId: pattern.id,
      sourcePatternName: pattern.name,
      ruleType: rule.type,
      fileTypes: ["tsx", "jsx", "ts"]
    });
  }
  if (pattern.antiPatterns) {
    for (let i = 0; i < pattern.antiPatterns.length; i++) {
      const ap = pattern.antiPatterns[i];
      if (!ap) continue;
      const regex = ap.badExample ? extractCodePattern(ap.badExample) : extractFromDescription(ap.description);
      if (!regex) {
        skipped.push({
          rule: { type: "must_not", description: ap.description, severity: "warning" },
          reason: "Could not extract pattern from anti-pattern"
        });
        continue;
      }
      rules.push({
        id: `${pattern.name}.anti-${i}`,
        description: ap.description,
        pattern: regex,
        severity: "warning",
        dimension,
        message: `Anti-pattern: ${ap.description}`,
        fix: ap.rationale,
        sourcePatternId: pattern.id,
        sourcePatternName: pattern.name,
        ruleType: "must_not",
        fileTypes: ["tsx", "jsx", "ts"]
      });
    }
  }
  return {
    rules,
    skipped,
    source: {
      patternId: pattern.id,
      patternName: pattern.name,
      ruleCount: pattern.rules.length + (pattern.antiPatterns?.length ?? 0),
      compiledCount: rules.length
    }
  };
}
function compilePatterns(patterns) {
  const allRules = [];
  const allSkipped = [];
  let totalRules = 0;
  for (const pattern of patterns) {
    const result = compilePattern(pattern);
    allRules.push(...result.rules);
    if (result.skipped.length > 0) {
      allSkipped.push(result.skipped);
    }
    totalRules += result.source.ruleCount;
  }
  return {
    rules: allRules,
    skipped: allSkipped,
    stats: {
      patterns: patterns.length,
      rules: totalRules,
      compiled: allRules.length,
      skipped: totalRules - allRules.length
    }
  };
}

