      component: normalizedName,
      description: component.description,
      props: component.props,
      presets: component.presets,
      commonMistakes: component.commonMistakes ?? [],
      guidance: component.guidance ?? "",
      relatedComponents: component.relatedComponents,
      importStatement: `import { ${this.capitalize(normalizedName)} } from '${component.importPath}';`,
      format
