/**
 * Pure decisions for gateway full mode (PRE-2873 step 2).
 *
 * Design: docs/architecture/github-action-gateway-validation.md.
 *
 * No imports from @actions/* or the MCP SDK, so every decision here is unit
 * tested directly under tsx (the same split as unchecked-gate.ts and
 * severity.ts). The side-effecting client lives in gateway-client.ts.
 */

import type { ActionConfig, ActionViolation } from './types.js';

export type ValidationMode = 'basic' | 'legacy' | 'gateway';

export type ModeDecision =
  | { ok: true; mode: ValidationMode }
  | { ok: false; error: string };

/**
 * Decide the validation mode from the configured inputs only.
 *
 * Whether an OIDC token can be minted is a runtime fact, so it never picks the
 * mode: it only picks the credential inside gateway mode. Every combination is
 * defined, and the one that used to silently run basic mode (a design system
 * id with only half of the Supabase pair) is now a configuration error.
 */
export function resolveValidationMode(
  config: Pick<ActionConfig, 'designSystemId' | 'supabaseUrl' | 'supabaseKey'>,
): ModeDecision {
  if (!config.designSystemId) return { ok: true, mode: 'basic' };
  const hasUrl = !!config.supabaseUrl;
  const hasKey = !!config.supabaseKey;
  if (hasUrl && hasKey) return { ok: true, mode: 'legacy' };
  if (hasUrl !== hasKey) {
    const set = hasUrl ? 'supabase-url' : 'supabase-key';
    const missing = hasUrl ? 'supabase-key' : 'supabase-url';
    return {
      ok: false,
      error:
        `design-system-id and ${set} are set but ${missing} is not. Remove both Supabase inputs ` +
        'to validate through the preset AI gateway (recommended), or set both to keep the deprecated direct mode.',
    };
  }
  return { ok: true, mode: 'gateway' };
}

/**
 * The MCP endpoint for a gateway base URL. `mcp-gateway-url` is a base: the
 * callback appends `/v1/agent-events` to it, and the MCP transport is served at
 * `/mcp` under the same base.
 */
export function mcpEndpoint(base: string): string {
  return `${base.replace(/\/+$/, '')}/mcp`;
}

// Same line the gateway writes (supabase/functions/mcp-gateway/bound-tenant-instructions.ts).
const BOUND_ID_RE = /^Design system id:\s*([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\.\s*$/gim;
// Any line that claims to state the id, well-formed or not.
const ID_LINE_RE = /^\s*Design system id:/gim;
const BOUND_LABEL_RE = /^Connected to:\s*(.+?)\.\s*$/m;

export interface BoundTenant {
  /** The design system id the gateway bound this credential to, or null when it did not say. */
  id: string | null;
  /** True when more than one line claims to state the id: the response is not trusted. */
  ambiguous: boolean;
  /** The human label from the `Connected to:` line, or null. Advisory only. */
  label: string | null;
}

export function parseBoundTenant(instructions: string | undefined | null): BoundTenant {
  const text = instructions ?? '';
  const ids = [...text.matchAll(BOUND_ID_RE)].map((m) => (m[1] ?? '').toLowerCase());
  const claims = text.match(ID_LINE_RE)?.length ?? 0;
  // Exactly one well-formed id line, and no other line claiming to be one.
  // A second claim (for example a customer-named design system forging the
  // line) makes the whole statement untrusted (Codex, #2643 round 1).
  const ambiguous = claims > 1;
  return {
    id: !ambiguous && ids.length === 1 ? (ids[0] ?? null) : null,
    ambiguous,
    label: text.match(BOUND_LABEL_RE)?.[1]?.trim() ?? null,
  };
}

/**
 * Compare the configured design system with the one the gateway bound. Returns
 * null when they match, otherwise the failure message. A gateway that does not
 * state the id fails too: the check must not be skippable by an older or
 * self-hosted gateway.
 */
export function tenantMismatch(configuredId: string, bound: BoundTenant): string | null {
  if (bound.ambiguous) {
    return (
      'The preset AI gateway stated more than one design system id for this credential, so design-system-id ' +
      'cannot be checked against it. Failing rather than guessing which one applies.'
    );
  }
  if (!bound.id) {
    return (
      'The preset AI gateway did not state which design system this credential is bound to, so ' +
      'design-system-id cannot be checked. Update the gateway, or point mcp-gateway-url at one that states it.'
    );
  }
  if (bound.id === configuredId.trim().toLowerCase()) return null;
  return (
    `design-system-id is ${configuredId}, but this credential is bound to ${bound.id}` +
    `${bound.label ? ` (${bound.label})` : ''}. The gateway always validates against the bound design system, ` +
    'so fix design-system-id or use the credential for the right one.'
  );
}

/** What the fetch wrapper records about the most recent non-2xx response. */
export interface HttpFailure {
  status: number;
  /** Parsed `Retry-After` in seconds, or null. */
  retryAfterSeconds: number | null;
  /** Response body text (truncated by the recorder). */
  body: string;
}

export type FailureClass =
  | { kind: 'transient'; waitSeconds: number; detail: string }
  | { kind: 'terminal'; message: string };

const DEFAULT_WAIT_S = 5;

interface JsonRpcErrorBody {
  error?: {
    code?: number;
    message?: string;
    data?: { type?: string; code?: string; hint?: string; retryAfterSeconds?: number; bucket?: string };
  };
  hint?: string;
  code?: string;
}

function parseBody(body: string): JsonRpcErrorBody | null {
  try {
    return JSON.parse(body) as JsonRpcErrorBody;
  } catch {
    return null;
  }
}

/**
 * Classify a non-2xx gateway response.
 *
 * Transient (waited out, then retried): a 429 whose JSON-RPC `error.data.type`
 * is `burst` or `rpm`, and a 503 `RATE_LIMIT_UNAVAILABLE`. Everything else is
 * terminal, including a monthly 429 in either allowance bucket: the Action does
 * not degrade on exhausted allowance (the doctrine gate does, by its own
 * contract), because a run that could not check must not pass.
 */
export function classifyHttpFailure(f: HttpFailure): FailureClass {
  const parsed = parseBody(f.body);
  const data = parsed?.error?.data;
  const hint = data?.hint ?? parsed?.hint;
  const wait = (): number =>
    f.retryAfterSeconds ?? (typeof data?.retryAfterSeconds === 'number' ? data.retryAfterSeconds : DEFAULT_WAIT_S);

  if (f.status === 429) {
    if (data?.type === 'burst' || data?.type === 'rpm') {
      return { kind: 'transient', waitSeconds: wait(), detail: `rate limit (${data.type})` };
    }
    if (data?.type === 'monthly') {
      return {
        kind: 'terminal',
        message: `The preset AI gateway's monthly allowance is used up${data.bucket ? ` (${data.bucket})` : ''}. ${hint ?? ''}`.trim(),
      };
    }
    return { kind: 'terminal', message: `The preset AI gateway refused the request (429). ${hint ?? ''}`.trim() };
  }
  if (f.status === 503 && data?.code === 'RATE_LIMIT_UNAVAILABLE') {
    return { kind: 'transient', waitSeconds: wait(), detail: 'rate limiter unavailable (503)' };
  }
  if (f.status === 401 || f.status === 403) {
    const code = data?.code ?? parsed?.code ?? parsed?.error?.message;
    return {
      kind: 'terminal',
      message:
        `The preset AI gateway rejected the credential (${f.status}${code ? ` ${code}` : ''}). ` +
        `${hint ?? 'Check that the preset AI GitHub App is installed for this repository and the job grants id-token: write, or check preset-api-key.'}`,
    };
  }
  return { kind: 'terminal', message: `The preset AI gateway returned HTTP ${f.status}: ${f.body.slice(0, 200)}` };
}

/** Parse a `Retry-After` header value in seconds. HTTP-date form is not used by the gateway. */
export function parseRetryAfter(value: string | null): number | null {
  if (value == null || value.trim() === '') return null;
  const n = Number(value.trim());
  return Number.isFinite(n) && n >= 0 ? n : null;
}

/** Caps from the plan: each wait at most 60s, at most 5 minutes of waiting per run. */
export const MAX_SINGLE_WAIT_S = 60;
export const MAX_TOTAL_WAIT_S = 300;
export const MIN_WAIT_S = 1;

/**
 * A per-run wait budget. `take(seconds)` returns the seconds to actually wait,
 * or null when waiting would exceed the run's total budget (the caller then
 * fails closed).
 */
export function createWaitBudget(totalSeconds = MAX_TOTAL_WAIT_S, singleCap = MAX_SINGLE_WAIT_S) {
  let spent = 0;
  return {
    take(seconds: number): number | null {
      // At least 1s per wait: a gateway answering Retry-After: 0 forever must
      // still exhaust the budget instead of spinning (Codex, #2643 round 2).
      const w = Math.min(Math.max(Number.isFinite(seconds) ? seconds : MIN_WAIT_S, MIN_WAIT_S), singleCap);
      if (spent + w > totalSeconds) return null;
      spent += w;
      return w;
    },
    get spent() {
      return spent;
    },
  };
}

/** Minimal shape of a validate_code result the Action reads. */
export interface GatewayViolation {
  rule?: string;
  ruleId?: string;
  found?: string;
  fix?: string;
  severity?: string;
  line?: number;
  fixCode?: string;
}

export interface ParsedValidateResult {
  violations: GatewayViolation[];
  /** Null when the result carried no coverage, which the caller treats as unchecked. */
  bindingRules: number | null;
}

/**
 * Why a violation entry cannot be used, or null when it can. Every field the
 * Action reads is checked, so a malformed entry fails the run as a gateway
 * failure instead of crashing a reporter later (Codex, #2643 round 1).
 */
function violationProblem(v: unknown): string | null {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return 'not an object';
  const o = v as Record<string, unknown>;
  for (const k of ['rule', 'ruleId', 'found', 'fix', 'severity', 'fixCode'] as const) {
    if (o[k] !== undefined && o[k] !== null && typeof o[k] !== 'string') return `${k} is not a string`;
  }
  if (o.line !== undefined && o.line !== null && typeof o.line !== 'number') return 'line is not a number';
  if (typeof o.rule !== 'string' && typeof o.ruleId !== 'string') return 'no rule or ruleId';
  return null;
}

/**
 * Parse a `validate_code` tool result (MCP content array with one JSON text
 * block). Throws on a tool error or a body that is not the documented shape:
 * a result the Action cannot read is a failure, never an empty pass.
 */
export function parseValidateResult(result: unknown): ParsedValidateResult {
  const r = result as { isError?: boolean; content?: Array<{ type?: string; text?: string }> } | null;
  const text = r?.content?.find((c) => c?.type === 'text')?.text;
  if (r?.isError) {
    throw new Error(`validate_code returned an error: ${(text ?? '').slice(0, 300)}`);
  }
  if (typeof text !== 'string') throw new Error('validate_code returned no text content');
  let body: { valid?: unknown; violations?: unknown; coverage?: { bindingRules?: unknown } };
  try {
    body = JSON.parse(text);
  } catch {
    throw new Error(`validate_code returned non-JSON content: ${text.slice(0, 200)}`);
  }
  if (!body || typeof body !== 'object' || Array.isArray(body)) throw new Error('validate_code result is not a JSON object');
  // Same contract the doctrine gate enforces (scripts/museum-doctrine-response.mjs).
  if (typeof body.valid !== 'boolean') throw new Error('validate_code result has no boolean "valid"');
  if (!Array.isArray(body.violations)) throw new Error('validate_code result has no violations array');
  body.violations.forEach((v, i) => {
    const problem = violationProblem(v);
    if (problem) throw new Error(`validate_code result violation ${i} is malformed: ${problem}`);
  });
  // `valid` is computed as `errors === 0` (packages/mcp/src/tools/validate.ts),
  // so valid:false with no error-severity violation is self-contradictory: the
  // engine declared the code invalid and gave nothing to fail on. Same rule as
  // the doctrine gate (scripts/museum-doctrine-response.mjs); Codex, #2643 round 4.
  const violations = body.violations as Array<{ severity?: unknown }>;
  if (body.valid === false && !violations.some((v) => (v.severity ?? 'warning') === 'error')) {
    throw new Error('validate_code returned valid:false with no error-severity violation to explain it');
  }
  const br = body.coverage?.bindingRules;
  // A count or nothing. A negative or fractional value is a malformed result,
  // never a pass (Codex, #2643 round 3).
  if (br !== undefined && br !== null && !(Number.isInteger(br) && (br as number) >= 0)) {
    throw new Error(`validate_code result coverage.bindingRules is not a non-negative integer (${JSON.stringify(br)})`);
  }
  return {
    violations: body.violations as GatewayViolation[],
    bindingRules: typeof br === 'number' ? br : null,
  };
}

/**
 * Map a design system violation (gateway result or the legacy in-process
 * validator, same shape) onto the Action's violation. All three severities
 * survive (PRE-2665). A missing or unknown severity reads as `warning`, the
 * same default the Museum doctrine gate applies.
 */
export function toActionViolation(v: GatewayViolation): ActionViolation {
  const severity: ActionViolation['severity'] =
    v.severity === 'error' || v.severity === 'warning' || v.severity === 'suggestion' ? v.severity : 'warning';
  const ruleId = v.ruleId ?? v.rule ?? 'design-system';
  return {
    rule: v.rule ?? ruleId,
    ruleId,
    found: v.found ?? '',
    fix: v.fix ?? '',
    severity,
    line: Number.isInteger(v.line) ? v.line : undefined,
    fixCode: v.fixCode,
  };
}
