/**
 * Orchestrates validation for all changed files (PRE-329).
 *
 * Two modes:
 * - Defaults: always runs afterGeneration() from @preset/core
 * - Full: when DB credentials provided, also runs DesignSystemValidator
 */

import { afterGeneration } from '@preset/core';
import { createClient } from '@preset/db';
// PRE-1658: import the CJS build explicitly. The default '@getfndd/mcp' entry is
// the ESM build, which carries a `createRequire(import.meta.url)` banner (added
// for the Deno-edge gateway bundle). ncc embeds that ESM build and runs it as
// CJS, where the banner's `const require` TDZ-crashes at load — breaking this
// Action (and health-scan) since 2026-06-01. The '/cjs' subpath resolves the
// banner-free dist/index.cjs. The gateway (explicit-path vendor) and the CLI
// (un-bundled dynamic import) keep using the ESM build.
import { DesignSystemValidator } from '@getfndd/mcp/cjs';
import type { ActionConfig, ActionResult, ActionViolation, ChangedFile, FileViolation } from './types.js';
import { resolveValidationMode, toActionViolation, type GatewayViolation } from './gateway-mode.js';
import { GatewayFailure, type GatewayConnection } from './gateway-client.js';
// PRE-1484 (W11) — static composition-conformance scorer for the hard PR-time gate.
import { scoreComposition } from '@preset/scanner';
import { tallySeverities } from './severity.js';

const JSX_FILE_RE = /\.(?:tsx|jsx|ts|js)$/i;

export async function validateFiles(
  files: ChangedFile[],
  config: ActionConfig,
  // PRE-2873 step 2: the open gateway connection in gateway full mode. Opened
  // (and closed) by index.ts, which runs the gateway preflight before its
  // zero-file return.
  gateway: GatewayConnection | null = null,
): Promise<ActionResult> {
  const modes: ('defaults' | 'full')[] = ['defaults'];
  const fileViolations: FileViolation[] = [];
  const byRule: Record<string, number> = {};
  let totalErrors = 0;
  let totalWarnings = 0;
  let totalSuggestions = 0;
  let uncheckedFiles = 0;
  let gatewayFailure: string | undefined;

  // Full mode: the deprecated direct read (legacy) or the gateway.
  const decision = resolveValidationMode(config);
  const mode = decision.ok ? decision.mode : 'basic';
  // Gateway mode with no connection means the preflight failed: index.ts
  // records that failure on the result, and every file counts as unchecked.
  if (mode === 'gateway') modes.push('full');
  let dbValidator: DesignSystemValidator | null = null;
  if (mode === 'legacy') {
    modes.push('full');
    const supabase = createClient(config.supabaseUrl!, config.supabaseKey!);
    dbValidator = new DesignSystemValidator({
      supabase,
      designSystemId: config.designSystemId!,
      layerId: config.layerId,
    });
  }

  for (const file of files) {
    const violations: ActionViolation[] = [];

    // 1. Run @preset/core defaults (always)
    const coreResult = afterGeneration(file.content, false);
    for (const v of coreResult.violations) {
      violations.push({
        rule: 'default',
        ruleId: v.patternId,
        found: v.match,
        fix: v.message,
        severity: v.severity,
        line: v.line,
        fixCode: v.fixCode,
      });
    }

    // 2. Run the design system's own rules (full mode).
    // PRE-2897: without a backend, no design system rule applies to this file at all.
    let dsViolations: GatewayViolation[] | null = null;
    if (gateway && mode === 'gateway' && !gatewayFailure) {
      try {
        const r = await gateway.validate({ code: file.content, filePath: file.path, layerId: config.layerId });
        // A result with no coverage is counted as unchecked, never as checked.
        if (r.bindingRules === null || r.bindingRules === 0) uncheckedFiles++;
        dsViolations = r.violations;
      } catch (err) {
        if (!(err instanceof GatewayFailure)) throw err;
        // Stop asking the gateway; the run fails on this. Remaining files still
        // get the core defaults so the comment shows what was found.
        gatewayFailure = err.message;
        uncheckedFiles++;
      }
    } else if (dbValidator) {
      const dbResult = await dbValidator.validate({
        code: file.content,
        filePath: file.path,
        includeDefaults: false, // we already ran defaults above
      });
      if (dbResult.coverage.bindingRules === 0) uncheckedFiles++;
      dsViolations = dbResult.violations as GatewayViolation[];
    } else {
      uncheckedFiles++;
    }
    if (dsViolations) {
      for (const raw of dsViolations) {
        const v = toActionViolation(raw);
        // Deduplicate: skip if same line + same rule already exists from defaults
        const isDupe = violations.some(existing => existing.line === v.line && existing.ruleId === v.ruleId);
        if (isDupe) continue;
        // All three severities survive (PRE-2665): `fail-on-warnings` must never
        // fail a PR on a rule parked as advisory (`suggestion`).
        violations.push(v);
      }
    }

    // 3. Run static composition-conformance (PRE-1484 first slice) — opt-in via
    //    `composition-checks` input. Universal rules only (forbidden Card>Card, max-depth,
    //    no-arbitrary-spacing); per-context DS-specific spacing checks are a later slice.
    //    Skip non-JSX/TSX files (the AST scorer can't parse them) and dedupe vs core/dbValidator.
    if (config.compositionChecks && JSX_FILE_RE.test(file.path)) {
      const compResult = scoreComposition(file.content);
      for (const f of compResult.findings) {
        const ruleId = f.rule;
        const isDupe = violations.some((existing) => existing.line === f.line && existing.ruleId === ruleId);
        if (isDupe) continue;
        violations.push({
          rule: 'composition',
          ruleId,
          found: f.selector,
          fix: f.detail,
          severity: f.severity,
          line: f.line,
        });
      }
    }

    if (violations.length > 0) {
      fileViolations.push({ path: file.path, violations });
    }

    // Aggregate counts. The three-way tally is pure and unit tested
    // (severity.ts): advisory findings must never land in `warnings`, which is
    // what `fail-on-warnings` gates on (PRE-2665).
    const tally = tallySeverities(violations);
    totalErrors += tally.errors;
    totalWarnings += tally.warnings;
    totalSuggestions += tally.suggestions;
    for (const v of violations) {
      byRule[v.ruleId] = (byRule[v.ruleId] ?? 0) + 1;
    }
  }

  const totalViolations = totalErrors + totalWarnings + totalSuggestions;

  // No threshold gates on advice. `fail-on-warnings` counts warnings only:
  // an advisory finding is surfaced, never a reason to fail (PRE-2665).
  const passed =
    (!config.failOnErrors || totalErrors === 0) &&
    (!config.failOnWarnings || totalWarnings === 0);

  return {
    passed,
    filesChecked: files.length,
    totalViolations,
    errors: totalErrors,
    warnings: totalWarnings,
    suggestions: totalSuggestions,
    uncheckedFiles,
    fileViolations,
    modes,
    byRule,
    ...(gatewayFailure ? { gatewayFailure } : {}),
  };
}
