/**
 * Pure markdown generation for the PR comment (PRE-2665).
 *
 * Split out of comment.ts, which imports `@actions/github` to post — that makes
 * the whole module unloadable under the tsx test runner, so this markdown was
 * untestable. It is the same reason `agent-events-callback-helpers.ts` exists.
 *
 * That mattered: the advisory tier shipped with a summary that contradicted
 * itself (badge said "Passed with 0 warnings" while the section below said
 * "Violations (N)"), and no test could have caught it from here.
 */

import type { ActionResult } from './types.js';
import { commentIcon } from './severity.js';
import { forkOrDependabotNotice } from './fork-detection.js';

export const COMMENT_MARKER = '<!-- preset-design-system-check -->';

const MAX_INLINE_VIOLATIONS = 30;

/**
 * Format health score section for the PR comment (PRE-613).
 */
function formatHealthScore(hs: NonNullable<ActionResult['healthScore']>): string {
  const lines: string[] = [];

  // Score badge with grade
  const deltaStr = hs.delta !== null
    ? ` (${hs.delta >= 0 ? '+' : ''}${hs.delta} from previous)`
    : '';

  lines.push(`### Health Score: **${hs.overall}/100** (${hs.grade})${deltaStr}`);
  lines.push('');

  // Dimension breakdown
  lines.push('| Dimension | Score |');
  lines.push('|-----------|------:|');
  lines.push(`| Token Adoption | ${hs.dimensions.tokenAdoption} |`);
  lines.push(`| Preset Adoption | ${hs.dimensions.presetAdoption} |`);
  lines.push(`| Accessibility | ${hs.dimensions.accessibility} |`);
  lines.push(`| Consistency | ${hs.dimensions.consistency} |`);

  // Threshold warnings
  if (!hs.passesThreshold) {
    lines.push('');
    lines.push('> [!CAUTION]');
    lines.push(`> Health score **${hs.overall}** is below the required threshold.`);
  }
  if (!hs.passesRegression) {
    lines.push('');
    lines.push('> [!CAUTION]');
    lines.push(`> Health score **regressed by ${Math.abs(hs.delta!)} points** from previous snapshot.`);
  }

  return lines.join('\n');
}

/** Escape user-controlled strings before embedding in markdown. */
function esc(text: string): string {
  return text
    .replace(/\\/g, '\\\\')
    .replace(/`/g, '\\`')
    .replace(/\*/g, '\\*')
    .replace(/\[/g, '\\[')
    .replace(/\]/g, '\\]')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

/** Oxford-free list join: "a", "a and b", "a, b and c". */
function joinParts(parts: string[]): string {
  if (parts.length <= 1) return parts.join('');
  return `${parts.slice(0, -1).join(', ')} and ${parts[parts.length - 1]}`;
}

/**
 * "found **N errors** and **M warnings**" (or just the warnings clause when
 * there are no errors). Shared by the ordinary failed-run banner and the
 * PRE-3040 forkGenericOnly banner's own failure clause, so the two can never
 * phrase the same count differently.
 */
function errorWarningClause(result: ActionResult): string {
  return result.errors > 0
    ? `found **${result.errors} error${result.errors !== 1 ? 's' : ''}** and **${result.warnings} warning${result.warnings !== 1 ? 's' : ''}**`
    : `found **${result.warnings} warning${result.warnings !== 1 ? 's' : ''}**`;
}

/**
 * PRE-3040: render a fork/Dependabot notice as "> **<lead>:** <rest>", bold
 * on the label only (the first colon-delimited clause) rather than the
 * whole sentence. `forkOrDependabotNotice` is the single source of the text
 * itself (shared with the Action log line in index.ts); this only adds the
 * markdown emphasis for the PR comment.
 */
function noticeBanner(notice: string): string {
  const colon = notice.indexOf(':');
  if (colon === -1) return `> **${notice}**`;
  return `> **${notice.slice(0, colon + 1)}**${notice.slice(colon + 1)}`;
}

/**
 * Trailing clause naming advisory findings on a FAILED run (PRE-2665). They did
 * not cause the failure and must not read as though they did, so they are
 * appended as context rather than folded into the failure count.
 */
function suggestionSuffix(result: ActionResult): string {
  if (result.suggestions <= 0) return '';
  return ` ${result.suggestions} suggestion${result.suggestions !== 1 ? 's' : ''} (advisory, not blocking).`;
}

export function generateMarkdown(result: ActionResult): string {
  const lines: string[] = [];

  lines.push(COMMENT_MARKER);
  lines.push('## Preset Design System Check');
  lines.push('');

  // Pass/fail badge.
  //
  // PRE-2873: `result.uncheckedGateFailed` is a SEPARATE reason from
  // `result.passed`, which stays scoped to the validator's own error/warning
  // thresholds. They are read independently below rather than folded into
  // one flag, specifically so a run that fails ONLY the unchecked-files gate
  // (passed === true, because there were no real errors/warnings) never gets
  // an error/warning count attributed to it, and so a run that fails for a
  // real threshold reason never gets "0 warnings" attributed to it either
  // (Codex rounds 1 and 2 on PRE-2873, in that order).
  const uncheckedGateFailed = !!result.uncheckedGateFailed;
  // PRE-2873 step 2: the gateway could not check the run. A third independent
  // reason, never folded into `passed`: a clean core-defaults result must not
  // read "All checks passed" when the design system's own rules never ran.
  const gatewayFailure = result.gatewayFailure;

  if (result.forkGenericOnly) {
    // PRE-3040: replace ONLY the lead sentence (what would otherwise be
    // "All checks passed"/"Passed with N findings" below) with the notice.
    // A real failure clause still appends underneath, unchanged, whenever
    // `!result.passed` is independently true (enforce mode tripped by the
    // generic checks themselves), the pinned interpretation of the plan's
    // internal contradiction (critique-1 #4). The notice never coexists
    // with the ordinary pass banner.
    //
    // PRE-3040 review (finding #3): `forkGenericOnlyReason` is optional on
    // `ActionResult` even though `forkGenericOnly` is a plain boolean, so
    // nothing in the type stops some future caller from setting one without
    // the other (today's only writer, index.ts, always sets both together).
    // A non-null assertion here would crash PR-comment generation for the
    // whole run on that gap; fall back to a reason-less generic notice
    // instead, so a missing reason degrades gracefully rather than throwing.
    const notice = result.forkGenericOnlyReason
      ? forkOrDependabotNotice(result.forkGenericOnlyReason)
      : 'Checked against generic rules only.';
    lines.push(noticeBanner(notice));
    if (!result.passed) {
      lines.push('> [!CAUTION]');
      lines.push(`> **Failed:** ${errorWarningClause(result)}.${suggestionSuffix(result)}`);
    }
  } else if (result.passed && !uncheckedGateFailed && !gatewayFailure) {
    if (result.errors === 0 && result.warnings === 0 && result.uncheckedFiles > 0) {
      // PRE-2897: no gate-eligible findings, but some files had no binding rules
      // behind them. "All checks passed" (or "Passed with N suggestions") would
      // certify code nobody checked. Keyed on errors/warnings, not totalViolations:
      // advisory-only findings are the normal case for a system whose rules are all
      // at `suggest`, and they must keep the disclaimer (Codex round 1).
      // This is the pass case: basic mode, or full mode with allow-unchecked.
      const all = result.uncheckedFiles >= result.filesChecked;
      lines.push(
        (all
          ? '> **No binding rules applied.** No errors or warnings were found, but none of the design system’s rules at warn or block apply to these files, so they were not checked against it. This is not a compliance pass.'
          : `> **No errors or warnings found**, but ${result.uncheckedFiles} of ${result.filesChecked} files had no binding design system rules (none at warn or block apply), so those files were not checked against it.`) +
          suggestionSuffix(result),
      );
    } else if (result.totalViolations === 0) {
      lines.push('> **All checks passed** — no design system violations found.');
    } else {
      // PRE-2665: an advisory-only result has warnings === 0 but
      // totalViolations > 0. Reporting "Passed with 0 warnings" above a
      // "Violations (N)" section contradicted itself and hid the new tier.
      const parts: string[] = [];
      // `passed` does not mean "nothing found": with fail-on-errors disabled a
      // run passes WITH errors. Listing only warnings and suggestions made such
      // a run claim it was clean.
      if (result.errors > 0) {
        parts.push(`**${result.errors} error${result.errors !== 1 ? 's' : ''}**`);
      }
      if (result.warnings > 0) {
        parts.push(`**${result.warnings} warning${result.warnings !== 1 ? 's' : ''}**`);
      }
      if (result.suggestions > 0) {
        parts.push(`**${result.suggestions} suggestion${result.suggestions !== 1 ? 's' : ''}**`);
      }
      lines.push(
        parts.length > 0
          ? `> **Passed** with ${joinParts(parts)} (not blocking).`
          : '> **Passed** — no design system violations found.',
      );
    }
  } else {
    // Failed. Up to two independent reasons, each named only when it
    // actually fired:
    //   1. a real threshold breach (!result.passed): errors and/or warnings.
    //   2. the PRE-2873 unchecked-files gate (uncheckedGateFailed).
    // Neither is inferred from the other. A run with fail-on-errors: false
    // that also hit the unchecked gate must not report its (non-blocking)
    // errors as a reason it failed (Codex round 2).
    const clauses: string[] = [];
    if (!result.passed) {
      clauses.push(errorWarningClause(result));
    }
    if (gatewayFailure) {
      clauses.push(`the preset AI gateway could not check this run against your design system (${gatewayFailure})`);
    }
    if (uncheckedGateFailed) {
      const all = result.uncheckedFiles >= result.filesChecked;
      clauses.push(
        all
          ? "none of the design system's rules at warn or block applied to the changed files, so full mode checked nothing against them (not a compliance pass)"
          : `${result.uncheckedFiles} of ${result.filesChecked} files had no binding design system rules applied`,
      );
    }
    lines.push('> [!CAUTION]');
    lines.push(`> **Failed:** ${joinParts(clauses)}.${suggestionSuffix(result)}`);
  }
  lines.push('');

  // Health score section (PRE-613)
  if (result.healthScore) {
    lines.push(formatHealthScore(result.healthScore));
    lines.push('');
  }

  // Summary table
  // PRE-2665: Suggestions is its own column. Without it the table showed 0/0
  // for an advisory-only run while the details below listed N violations.
  lines.push('| Files Checked | Errors | Warnings | Suggestions | Mode |');
  lines.push('|:---:|:---:|:---:|:---:|:---:|');
  lines.push(
    `| ${result.filesChecked} | ${result.errors} | ${result.warnings} | ${result.suggestions} | ${result.modes.join(' + ')} |`,
  );
  lines.push('');

  // Per-rule breakdown
  const ruleEntries = Object.entries(result.byRule).sort(([, a], [, b]) => b - a);
  if (ruleEntries.length > 0) {
    lines.push('**By Rule:**');
    lines.push('');
    lines.push('| Rule | Count |');
    lines.push('|------|------:|');
    for (const [rule, count] of ruleEntries) {
      lines.push(`| \`${esc(rule)}\` | ${count} |`);
    }
    lines.push('');
  }

  // Individual violations (capped)
  if (result.fileViolations.length > 0) {
    let shown = 0;
    const total = result.totalViolations;

    lines.push('<details>');
    lines.push(`<summary>Violations (${total})</summary>`);
    lines.push('');

    for (const fv of result.fileViolations) {
      if (shown >= MAX_INLINE_VIOLATIONS) break;

      lines.push(`**\`${esc(fv.path)}\`**`);
      lines.push('');

      for (const v of fv.violations) {
        if (shown >= MAX_INLINE_VIOLATIONS) break;
        const icon = commentIcon(v.severity);
        const lineRef = v.line ? `:${v.line}` : '';
        lines.push(`- ${icon} **${esc(v.ruleId)}**${lineRef} — ${esc(v.fix)}`);
        shown++;
      }
      lines.push('');
    }

    if (shown < total) {
      lines.push(`_...and ${total - shown} more_`);
      lines.push('');
    }

    lines.push('</details>');
    lines.push('');
  }

  lines.push('---');
  lines.push('_Generated by [preset AI](https://www.presetai.dev) Design System Check_');

  return lines.join('\n');
}
